/* ────────────────────────────────────────────────────────────────
   Grade-level select — markup, wiring, and readback
   ----------------------------------------------------------------
   Usage:
     1. Emit:  ${Pages.gradeLevelSelectHTML('cf-grade', currentValue)}
     2. Wire:  Pages.wireGradeLevelSelect(m.overlay, 'cf-grade');
     3. Read:  Pages.readGradeLevel(m.overlay, 'cf-grade');
   ──────────────────────────────────────────────────────────────── */

Pages.gradeLevelSelectHTML = function (id, selectedValue, opts = {}) {
  const current = String(selectedValue || '').trim();
  const isKnown = GRADE_LEVELS.includes(current);
  const allowCustom = opts.allowCustom !== false;
  const includeBlank = opts.includeBlank !== false;

  // Preserve an existing non-canonical value (e.g. "Grade 9 - SSC") as a
  // one-off option so editing old records never silently drops it.
  const legacyOption = (current && !isKnown)
    ? `<option value="${Utils.attr(current)}" selected>${Utils.esc(current)}</option>`
    : '';

  return `
    <select class="form-control" id="${Utils.attr(id)}" data-grade-select>
      ${includeBlank ? `<option value="" ${!current ? 'selected' : ''}>— Select grade level —</option>` : ''}
      ${GRADE_LEVELS.map(g =>
        `<option value="${Utils.attr(g)}" ${g === current ? 'selected' : ''}>${Utils.esc(g)}</option>`
      ).join('')}
      ${legacyOption}
      ${allowCustom ? `<option value="__custom__">Custom…</option>` : ''}
    </select>
    ${allowCustom ? `
      <input class="form-control" id="${Utils.attr(id)}-custom"
             placeholder="Type the custom grade level"
             style="margin-top:6px;display:${(current && !isKnown) ? 'block' : 'none'};"
             value="${(current && !isKnown) ? Utils.attr(current) : ''}">
    ` : ''}
  `;
};

Pages.wireGradeLevelSelect = function (root, id) {
  if (!root) return;
  const sel = root.querySelector('#' + CSS.escape(id));
  const custom = root.querySelector('#' + CSS.escape(id) + '-custom');
  if (!sel || !custom) return;
  const sync = () => {
    const isCustom = sel.value === '__custom__';
    custom.style.display = isCustom ? 'block' : 'none';
    if (isCustom && document.activeElement !== custom) custom.focus();
  };
  sel.addEventListener('change', sync);
  sync();
};

Pages.readGradeLevel = function (root, id) {
  if (!root) return '';
  const sel = root.querySelector('#' + CSS.escape(id));
  if (!sel) return '';
  if (sel.value === '__custom__') {
    const custom = root.querySelector('#' + CSS.escape(id) + '-custom');
    return custom ? custom.value.trim() : '';
  }
  return sel.value;
};

/* ============================================================================
   ASSESSMENT · MULTI-CLASS ASSIGNMENT HELPERS
   ----------------------------------------------------------------------------
   Attached to Pages AFTER the main object literal so a syntax slip can never
   silently break the whole Pages object. Every page that needs multi-class
   assessment support relies on these three functions.
   ============================================================================ */

/** Return the list of class IDs this assessment is available in. */
Pages._assessmentClassIds = function (a) {
  if (!a) return [];
  if (Array.isArray(a.classIds) && a.classIds.length) return a.classIds.slice();
  if (a.classId) return [a.classId];
  return [];
};

/** True when the given assessment should appear for the given class. */
Pages._assessmentAppliesToClass = function (a, classId) {
  if (!a) return false;
  const ids = Pages._assessmentClassIds(a);
  // Legacy / unattached assessments are shown everywhere so nothing
  // silently disappears.
  if (!ids.length) return true;
  if (!classId) return true;
  return ids.includes(classId);
};

/** Open the "Assign to Classes" modal for one assessment. */
Pages.openAssignAssessmentModal = async function (assessmentId) {
  const a = await DB.get('assessments', assessmentId);
  if (!a) { UI.toast('Assessment not found.', 'error'); return; }

  const classes = State.classes.slice().sort((x, y) =>
    (x.gradeLevel + ' ' + x.section).localeCompare(y.gradeLevel + ' ' + y.section)
  );
  if (!classes.length) {
    UI.toast('Create a class first.', 'warning');
    return;
  }

  const originallyOwnedId = a.classId || null;
  const selected = new Set(Pages._assessmentClassIds(a));

  const m = UI.modal({
    title: 'Assign Assessment to Classes',
    size: 'modal-lg',
    body: `
      <p class="text-sm text-muted mb-12">
        Choose which classes can see <strong>${Utils.esc(a.title || 'this assessment')}</strong>
        in the Gradebook, Quiz Manager, and Assessment Builder. Scores are always
        recorded against the class you're currently signed into — assigning an
        assessment to more classes does not merge or move any existing results.
      </p>

      <div class="flex gap-8 mb-12" style="flex-wrap:wrap;">
        <button type="button" class="btn btn-sm btn-outline" id="aa-select-all">Select all</button>
        <button type="button" class="btn btn-sm btn-outline" id="aa-select-none">Clear</button>
        ${originallyOwnedId ? `<button type="button" class="btn btn-sm btn-ghost" id="aa-select-owner">Only the original class</button>` : ''}
      </div>

      <div style="max-height:400px;overflow-y:auto;border:1px solid var(--border);border-radius:10px;">
        ${classes.map(c => {
          const isOwner = c.id === originallyOwnedId;
          const isChecked = selected.has(c.id);
          return `
            <label class="aa-class-row"
                   style="display:flex;gap:12px;align-items:center;padding:12px 14px;
                          border-bottom:1px solid var(--border);cursor:pointer;
                          background:${isChecked ? 'var(--light-blue)' : 'transparent'};">
              <input type="checkbox" class="aa-class-cb" value="${Utils.attr(c.id)}"
                     ${isChecked ? 'checked' : ''}
                     style="width:16px;height:16px;accent-color:var(--deped-blue);flex-shrink:0;">
              <div style="flex:1;min-width:0;">
                <div style="font-weight:700;font-size:13px;">
                  ${Utils.esc(c.gradeLevel || '')}${c.gradeLevel && c.section ? ' – ' : ''}${Utils.esc(c.section || '')}
                  ${isOwner ? '<span class="badge badge-blue" style="font-size:9px;margin-left:6px;">Original</span>' : ''}
                </div>
                <div class="text-xs text-muted" style="margin-top:2px;">
                  ${Utils.esc(c.subject || 'No subject')}${c.schoolYear ? ' · SY ' + Utils.esc(c.schoolYear) : ''}
                </div>
              </div>
            </label>`;
        }).join('')}
      </div>

      <div id="aa-error" class="auth-error mt-12" role="alert" aria-live="polite"></div>
    `,
    footer: `
      <button class="btn btn-outline" data-cancel>Cancel</button>
      <button class="btn btn-primary" id="aa-save">${icon('save')} Save Assignment</button>
    `
  });

  const overlay = m.overlay;
  const cbs = () => overlay.querySelectorAll('.aa-class-cb');
  const syncRows = () => {
    overlay.querySelectorAll('.aa-class-row').forEach(row => {
      const cb = row.querySelector('.aa-class-cb');
      row.style.background = cb.checked ? 'var(--light-blue)' : 'transparent';
    });
  };

  overlay.querySelector('#aa-select-all').onclick = () => {
    cbs().forEach(cb => { cb.checked = true; });
    syncRows();
  };
  overlay.querySelector('#aa-select-none').onclick = () => {
    cbs().forEach(cb => { cb.checked = false; });
    syncRows();
  };
  const ownerBtn = overlay.querySelector('#aa-select-owner');
  if (ownerBtn) ownerBtn.onclick = () => {
    cbs().forEach(cb => { cb.checked = cb.value === originallyOwnedId; });
    syncRows();
  };

  overlay.querySelectorAll('.aa-class-cb').forEach(cb => {
    cb.addEventListener('change', syncRows);
  });

  overlay.querySelector('[data-cancel]').onclick = m.close;

  overlay.querySelector('#aa-save').onclick = async () => {
    const errEl = overlay.querySelector('#aa-error');
    errEl.classList.remove('show');

    const chosen = Array.from(cbs()).filter(cb => cb.checked).map(cb => cb.value);
    if (!chosen.length) {
      errEl.textContent = 'Assign this assessment to at least one class.';
      errEl.classList.add('show');
      return;
    }

    try {
      const fresh = await DB.get('assessments', assessmentId) || a;
      fresh.classIds = chosen;
      if (!fresh.classId) fresh.classId = chosen[0];
      fresh.updatedAt = new Date().toISOString();

      await DB.put('assessments', fresh);

      App.logActivity(
        `Assessment "${a.title || ''}" assigned to ${chosen.length} class${chosen.length === 1 ? '' : 'es'}`,
        'Assessments'
      );

      m.close();
      UI.toast(
        `Assigned to ${chosen.length} class${chosen.length === 1 ? '' : 'es'}`,
        'success'
      );

      // Refresh whichever page launched this modal.
      if (State.currentModule === 'gradebook') {
        App.navigate('gradebook');
      } else if (State.currentModule === 'assessment-builder') {
        App.navigate('assessment-builder');
      } else if (State.currentModule === 'quiz-manager') {
        App.navigate('quiz-manager');
      } else {
        App.navigate(State.currentModule || 'dashboard');
      }
    } catch (e) {
      console.error('[Assign] Save failed:', e);
      errEl.textContent = 'Could not save: ' + (e.message || 'unknown error');
      errEl.classList.add('show');
    }
  };
};

/* ============================================================================
   SYNC OVER WIFI
   ----------------------------------------------------------------------------
   Peer-to-peer device sync using WebRTC data channels.

   Architecture:
     • The sending device generates a short room code.
     • PeerJS's public signalling server is used ONLY to exchange the initial
       SDP/ICE handshake. No learner data ever touches it.
     • Once the channel opens, the entire transfer runs directly between the
       two browsers. On the same LAN, WebRTC prefers the local host candidate,
       so the bulk of the traffic stays on your WiFi.

   Data model:
     • A full JSON snapshot is built with the same shape as
       Pages.backupAll() produces — it's then chunked into 16 KB pieces
       and streamed across the channel with progress callbacks.
     • One-way by design: sender → receiver. To go the other direction,
       swap roles. This is simpler and easier to reason about than trying
       to run a two-phase bidirectional merge over a live socket.

   Security:
     • WebRTC data channels are DTLS-encrypted end-to-end.
     • The room code is 6 characters from a 32-char alphabet (~10^9 combos)
       and is only live while the host modal stays open.
     • Only one peer can join a given code; a second join attempt is
       rejected.
   ============================================================================ */
/* ============================================================================
   SYNC OVER WIFI
   ----------------------------------------------------------------------------
   Peer-to-peer device sync using WebRTC data channels.

   Architecture:
     • The sending device generates a short room code.
     • PeerJS's public signalling server is used ONLY to exchange the initial
       SDP/ICE handshake. No learner data ever touches it.
     • Once the channel opens, the entire transfer runs directly between the
       two browsers. On the same LAN, WebRTC prefers the local host candidate,
       so the bulk of the traffic stays on your WiFi.

   Handshake (fixed — no more duplicate sends):
     1. Both peers see the data channel open.
     2. The RECEIVER sends { type: 'ready-to-receive' }.
     3. The SENDER waits for that message, then sends the snapshot exactly once.
     4. The RECEIVER reassembles, applies, and replies { type: 'applied' }.

   Security:
     • WebRTC data channels are DTLS-encrypted end-to-end.
     • The room code is 6 characters from a 32-char alphabet (~10^9 combos)
       and is only live while the host modal stays open.
     • Only one peer can join a given code; a second join attempt is rejected.
   ============================================================================ */
const SyncManager = {
  _peer: null,
  _conn: null,
  _role: null,          // 'host' | 'guest'
  _mode: 'send',        // 'send' | 'receive'
  _code: null,
  _snapshot: null,
  _recvChunks: [],
  _recvTotal: 0,
  _recvSize: 0,
  _sendSize: 0,
  _sendSent: 0,
  _onProgress: null,
  _onComplete: null,
  _onError: null,
  _libLoaded: false,
  _sessionToken: null,        // ← NEW: invalidates stale async callbacks
  _guestConnecting: false,    // guest: peer.connect() already issued for this session
  _stopHostIce: null,         // host: disposer for the ICE watcher

  // ── Handshake / guard state ──
  _guestReady: false,   // host: receiver signalled it's ready
  _sent: false,         // host: snapshot already sent (prevents duplicate)
  _handshakeDone: false,// both: the open handshake already ran
  _recvWatchdog: null,  // receiver: fires if the sender stalls or never starts
  _ackWatchdog: null,   // sender: fires if the receiver never confirms
  _ackResolver: null,   // receiver: held ref so 'applied-ok' can cancel the wait
  _lastMetaAt: 0,
  _recvDone: false,
  _finished: false,
  _timedOut: false,
  _retryCount: 0,

  // ── Setting keys that must NEVER travel in a sync payload ──
  // The receiving device keeps its own credentials, API keys, and license.
  // These are also filtered out of `Pages.backupAll` and honoured by
  // `MergeEngine.SKIP_STORES`, so excluding them here keeps the three
  // transports consistent.
  SENSITIVE_SETTING_KEYS: new Set([
    'auth.account',
    'geminiApiKey',
    'geminiModel',
    'web3formsKey',
    'pollinationsApiKey',
    'emailSendMethod',
    'license.current',
    'gradingPolicyOverrides'
  ]),

  /* ---------- lib loader ---------- */
_peerCtor() {
  const w = window;
  if (typeof w.Peer === 'function') return w.Peer;
  if (w.peerjs && typeof w.peerjs.Peer === 'function') { w.Peer = w.peerjs.Peer; return w.Peer; }
  return null;
},

/* ---------- connection options ----------
   PeerJS's built-in defaults are a single public STUN list and NO TURN relay.
   On school / guest WiFi (client isolation, blocked mDNS) the direct LAN path
   cannot form and nothing else is available, so the channel never opens.
   We pass an explicit ICE list and let a TURN relay be configured as a fallback:
     localStorage['klaz.sync.iceServers'] = JSON array of RTCIceServer objects
     localStorage['klaz.sync.peerServer'] = JSON {host,port,path,secure,key}   */
_readJsonSetting(key) {
  try { const v = localStorage.getItem(key); return v ? JSON.parse(v) : null; }
  catch (e) { return null; }
},
_peerOptions() {
  const extra = this._readJsonSetting('klaz.sync.iceServers');
  const iceServers = [
    { urls: ['stun:stun.l.google.com:19302', 'stun:stun1.l.google.com:19302',
             'stun:stun2.l.google.com:19302'] },
    { urls: 'stun:stun.cloudflare.com:3478' },
    { urls: 'stun:global.stun.twilio.com:3478' }
  ];
  if (Array.isArray(extra)) iceServers.push(...extra);
  const opts = { debug: 1, config: { iceServers, iceCandidatePoolSize: 4 } };
  const srv = this._readJsonSetting('klaz.sync.peerServer');
  if (srv && typeof srv === 'object' && srv.host) Object.assign(opts, srv);
  return opts;
},

/* Watch ICE on a data connection so a dead path fails in seconds with a
   useful message instead of a silent 60 s hang. Returns a disposer. */
_watchIce(conn, onFailed) {
  let pc = null, timer = null, stopped = false;
  const handler = () => {
    if (stopped || !pc) return;
    const st = pc.iceConnectionState;
    console.log('[Sync] ICE state:', st);
    if (st === 'failed') { stopped = true; onFailed(); }
  };
  const attach = () => {
    pc = conn && conn.peerConnection;
    if (!pc) return false;
    pc.addEventListener('iceconnectionstatechange', handler);
    return true;
  };
  if (!attach()) {
    let tries = 0;
    timer = setInterval(() => {
      if (stopped || attach() || ++tries > 50) { clearInterval(timer); timer = null; }
    }, 100);
  }
  return () => {
    stopped = true;
    if (timer) clearInterval(timer);
    try { if (pc) pc.removeEventListener('iceconnectionstatechange', handler); } catch (e) {}
  };
},
_ICE_FAIL_MSG:
  'The two devices found each other but could not open a direct link. ' +
  'This usually means the WiFi blocks device-to-device traffic ("client/AP isolation", ' +
  'common on school or guest WiFi). Try: a phone hotspot, the main (non-guest) WiFi, ' +
  'or turn off any VPN/private DNS on both devices.',

async _ensureLib() {
  if (this._peerCtor()) { this._libLoaded = true; return true; }

  // Already injected? Wait for it, but don't cache a failed promise.
  const src = './vendor/peerjs.min.js';
  const existing = document.querySelector(`script[src="${src}"]`);
  if (existing) {
    for (let i = 0; i < 60; i++) {          // up to 6 s
      if (this._peerCtor()) { this._libLoaded = true; return true; }
      await new Promise(r => setTimeout(r, 100));
    }
    console.warn('[Sync] peerjs.min.js present but window.Peer never appeared.');
    return false;
  }

  return new Promise((resolve) => {
    const s = document.createElement('script');
    s.src = src;
    s.async = true;
    s.onload = () => {
      // onload can fire a tick before the global is visible in some browsers
      setTimeout(() => { this._libLoaded = !!this._peerCtor(); resolve(this._libLoaded); }, 0);
    };
    s.onerror = () => {
      console.error('[Sync] Failed to load ./vendor/peerjs.min.js');
      try { s.remove(); } catch (e) {}   // allow a clean retry next time
      resolve(false);
    };
    document.head.appendChild(s);
  });
},

  /* ---------- code generator ---------- */
  _generateCode() {
    const A = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';   // no I/O/0/1
    let out = '';
    const bytes = new Uint8Array(6);
    crypto.getRandomValues(bytes);
    for (let i = 0; i < 6; i++) out += A[bytes[i] % A.length];
    return out;
  },
  _peerIdForCode(code) {
    return 'klazassist-' + String(code).toLowerCase();
  },

  /* ========================================================================
     HOST — the device that pushes its data out
     ======================================================================== */
async startHost(opts = {}) {
  if (this._peer || this._conn) this.close();

  const sessionToken = Utils.uid('sync-');       // ← NEW
  this._sessionToken = sessionToken;             // ← NEW
  const alive = () => this._sessionToken === sessionToken;   // ← NEW

  this._mode = opts.mode || 'send';
  this._role = 'host';
  this._onProgress = opts.onProgress || null;
  this._onComplete = opts.onComplete || null;
  this._onError    = opts.onError    || null;
  this._guestReady = false;
  this._sent = false;
  this._handshakeDone = false;
  this._finished = false;
  this._timedOut = false;
  this._recvDone = false;
  this._retryCount = opts._retryCount || 0;

  const ok = await this._ensureLib();
  if (!ok) {
    this._fail('Could not load the sync library. Make sure ./vendor/peerjs.min.js exists.');
    return null;
  }

  this._code = this._generateCode();
  const peerId = this._peerIdForCode(this._code);
  console.log('[Sync] Host starting with code', this._code, '(peer id:', peerId + ')');

  try {
    this._peer = new (this._peerCtor())(peerId, this._peerOptions());
  } catch (e) {
    this._fail('Could not start the sync service: ' + (e.message || 'unknown error'));
    return null;
  }

  return new Promise((resolve) => {
    let settled = false;
    const settle = (v) => { if (!settled) { settled = true; resolve(v); } };

    // (BUG #1 FIX) Fail fast if the signalling server never confirms our ID.
    let openTimeout = setTimeout(() => {
      if (!alive()) return;                                    // ← ADD
      if (!settled) {
        this._fail('Could not register with the sync server. Check your internet ' +
                   'connection, then try again.');
        settle(null);
      }
    }, 30000);

    const clearOpenTimeout = () => {
      if (openTimeout) { clearTimeout(openTimeout); openTimeout = null; }
    };

    this._peer.on('open', () => {
      // (BUG #5 FIX) Ignore if the peer was closed while we were waiting.
      if (!alive()) return;                                    // ← ADD
      if (!this._peer || this._finished) return;               // ← KEEP
      clearOpenTimeout();
      console.log('[Sync] Host peer is open on the signalling server.');
      this._progress({ phase: 'waiting', message: 'Waiting for the other device…' });
      settle(this._code);
    });

    // Signalling socket dropped (phone screen-off, WiFi blip). The room code is
    // un-registered while disconnected, so re-register under the SAME id.
    this._peer.on('disconnected', () => {
      if (!alive() || this._finished || !this._peer || this._peer.destroyed) return;
      console.warn('[Sync] Host lost the signalling server — reconnecting…');
      try { this._peer.reconnect(); } catch (e) {}
    });

    this._peer.on('connection', (conn) => {
      if (!alive()) { try { conn.close(); } catch (e) {} return; }   // ← ADD
      // (BUG #5 FIX)
      if (!this._peer || this._finished) {
        try { conn.close(); } catch (e) {}
        return;
      }
      clearOpenTimeout();
      console.log('[Sync] Host received incoming connection:', conn.peer);
      if (this._conn) {
        console.warn('[Sync] Rejecting second connection from', conn.peer);
        try { conn.close(); } catch (e) {}
        return;
      }
      this._conn = conn;
      this._wireConnection();
      if (this._stopHostIce) this._stopHostIce();
      this._stopHostIce = this._watchIce(conn, () => {
        if (!alive() || this._finished || conn.open) return;
        this._fail(this._ICE_FAIL_MSG);
        settle(null);
      });
      conn.on('open', () => { if (this._stopHostIce) { this._stopHostIce(); this._stopHostIce = null; } });
    });

    this._peer.on('error', (err) => {
      if (!alive()) return;                                    // ← ADD
      const errType = (err && err.type) || '';
      const errMsg  = (err && err.message) || String(err);
      console.error('[Sync] Host peer error:', errType, errMsg);

      if (errType === 'unavailable-id') {
        clearOpenTimeout();
        const nextRetry = (this._retryCount || 0) + 1;
        if (nextRetry > 3) {
          this._fail('Could not obtain a free room code after several attempts. ' +
                     'Please wait a minute and try again.');
          settle(null);
          return;
        }
        console.log('[Sync] Room code collided — regenerating (attempt ' + nextRetry + ').');
        try { this._peer.removeAllListeners(); } catch (e) {}
        this.close();
        this.startHost({ ...opts, _retryCount: nextRetry }).then(settle, () => settle(null));
        return;
      }

      clearOpenTimeout();
      let friendly;
      switch (errType) {
        case 'network':
          friendly = 'Lost connection to the sync server. Check your internet connection.';
          break;
        case 'server-error':
          friendly = 'The sync server is having problems. Please try again in a moment.';
          break;
        case 'browser-incompatible':
          friendly = 'This browser does not support the features needed for sync. ' +
                     'Try Chrome, Edge, Firefox, or Safari 15+.';
          break;
        case 'socket-error':
        case 'socket-closed':
          friendly = 'The connection to the sync server was lost. Reload the app and try again.';
          break;
        default:
          friendly = 'Sync error: ' + (errType || errMsg || 'unknown');
      }
      this._fail(friendly);
      settle(null);
    });

    setTimeout(() => {
      if (!alive()) return;                                    // ← ADD
      if (!this._conn && !this._timedOut) {
        this._timedOut = true;
        this._fail('No device joined within 3 minutes. The room code has expired.');
        settle(null);
      }
    }, 180000);
  });
},

  /* ========================================================================
     GUEST — the device that receives (or sends, if mode='send' is set)
     ======================================================================== */
async joinAsGuest(opts = {}) {
  if (this._peer || this._conn) this.close();

  const sessionToken = Utils.uid('sync-');                   // ← NEW
  this._sessionToken = sessionToken;                         // ← NEW
  const alive = () => this._sessionToken === sessionToken;   // ← NEW

  this._retryCount = 0;
  this._guestConnecting = false;
  const code = String(opts.code || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
  if (code.length !== 6) { this._fail('Room code must be 6 characters.'); return false; }

  this._mode = opts.mode || 'receive';
  this._role = 'guest';
  this._onProgress = opts.onProgress || null;
  this._onComplete = opts.onComplete || null;
  this._onError    = opts.onError    || null;
  this._guestReady = false;
  this._sent = false;
  this._handshakeDone = false;
  this._finished = false;

  const ok = await this._ensureLib();
  if (!ok) { this._fail('Could not load the sync library.'); return false; }

  this._code = code;
  console.log('[Sync] Guest joining with code', code);

  try {
    // (BUG #6 FIX) Pass options as the SOLE argument so PeerJS assigns
    // a fresh guest ID from the server. This is the documented pattern.
    this._peer = new (this._peerCtor())(this._peerOptions());
  } catch (e) {
    this._fail('Could not start the sync service: ' + (e.message || 'unknown error'));
    return false;
  }

  return new Promise((resolve) => {
    let settled = false;
    const settle = (v) => { if (!settled) { settled = true; resolve(v); } };

    // (BUG #1 FIX for guest) Fail fast if we can't even reach the server.
    let openTimeout = setTimeout(() => {
      if (!alive()) return;
      if (!settled) {
        this._fail('Could not reach the sync server. Check your internet ' +
                   'connection, then try again.');
        settle(false);
      }
    }, 30000);

    const clearOpenTimeout = () => {
      if (openTimeout) { clearTimeout(openTimeout); openTimeout = null; }
    };

    this._peer.on('disconnected', () => {
      if (!alive() || this._finished || !this._peer || this._peer.destroyed) return;
      console.warn('[Sync] Guest lost the signalling server — reconnecting…');
      try { this._peer.reconnect(); } catch (e) {}
    });

    this._peer.on('open', () => {
      if (!alive()) return; 
      if (!this._peer || this._finished) return;
      if (this._guestConnecting) return;          // 'open' re-fires after reconnect()
      this._guestConnecting = true;
      clearOpenTimeout();
      console.log('[Sync] Guest peer is open. Connecting to host…');
      this._progress({ phase: 'connecting', message: 'Connecting to the other device…' });

      let attempt = 0;
      const MAX_ATTEMPTS = 3, ATTEMPT_MS = 20000;
      let stopIce = null, attemptTimer = null;

      const tryConnect = () => {
        if (!alive() || settled || this._finished || !this._peer) return;
        attempt++;
        let conn;
        try {
          conn = this._peer.connect(this._peerIdForCode(code), { reliable: true });
        } catch (e) {
          this._fail('Could not open a connection to that room code: ' + (e.message || 'unknown'));
          settle(false);
          return;
        }
        this._conn = conn;
        this._wireConnection();
        console.log('[Sync] Guest connect attempt', attempt, 'of', MAX_ATTEMPTS);

        const retryOrGiveUp = () => {
          if (!alive() || settled || conn.open || this._conn !== conn) return;
          if (attemptTimer) { clearTimeout(attemptTimer); attemptTimer = null; }
          if (stopIce) { stopIce(); stopIce = null; }
          if (attempt < MAX_ATTEMPTS) {
            console.warn('[Sync] Attempt', attempt, 'failed — retrying with a fresh negotiation.');
            this._conn = null;
            try { conn.close(); } catch (e) {}
            tryConnect();
          } else {
            giveUp();
          }
        };

        stopIce = this._watchIce(conn, retryOrGiveUp);

        conn.on('open', () => {
          if (!alive() || this._conn !== conn) return;
          if (attemptTimer) { clearTimeout(attemptTimer); attemptTimer = null; }
          if (stopIce) { stopIce(); stopIce = null; }
          console.log('[Sync] Guest data channel is open.');
          settle(true);
        });

        attemptTimer = setTimeout(retryOrGiveUp, ATTEMPT_MS);
      };

      const giveUp = () => {
        if (!alive() || settled) return;
        if (attemptTimer) { clearTimeout(attemptTimer); attemptTimer = null; }
        if (stopIce) { stopIce(); stopIce = null; }
        this._fail(this._ICE_FAIL_MSG + ' Also double-check the code and that the sender\'s ' +
                   'window is still open.');
        settle(false);
      };

      tryConnect();
    });

    this._peer.on('error', (err) => {
      if (!alive()) return;                                    // ← ADD
      const errType = (err && err.type) || '';
      const errMsg  = (err && err.message) || String(err);
      console.error('[Sync] Guest peer error:', errType, errMsg);
      clearOpenTimeout();

      // (BUG #4 FIX) Give the user a specific, actionable message.
      let friendly;
      switch (errType) {
        case 'peer-unavailable':
          friendly =
            'The other device is not reachable. Common causes:\n' +
            '• The room code was typed incorrectly (check every character).\n' +
            '• The sender\'s "Sending data" modal was closed.\n' +
            '• The sender\'s device lost its internet connection.';
          break;
        case 'network':
          friendly = 'Lost connection to the sync server. Check your internet connection.';
          break;
        case 'server-error':
          friendly = 'The sync server is having problems. Please try again in a moment.';
          break;
        case 'browser-incompatible':
          friendly = 'This browser does not support the features needed for sync. ' +
                     'Try Chrome, Edge, Firefox, or Safari 15+.';
          break;
        case 'unavailable-id':
          // Should not normally happen on the guest because we don't
          // specify an ID, but handle it defensively.
          friendly = 'The server could not assign an ID for this device. ' +
                     'Reload the app and try again.';
          break;
        case 'socket-error':
        case 'socket-closed':
          friendly = 'The connection to the sync server was lost. Reload the app and try again.';
          break;
        default:
          friendly = 'Sync error: ' + (errType || errMsg || 'unknown');
      }
      this._fail(friendly);
      settle(false);
    });
  });
},

  /* ========================================================================
     WIRE THE DATA CHANNEL
     ======================================================================== */
_wireConnection() {
  const conn = this._conn;
  if (!conn) return;

  const sessionToken = this._sessionToken;                     // ← ADD
  const alive = () => this._sessionToken === sessionToken;     // ← ADD

  const doHandshake = () => {
    if (!alive()) return;                                      // ← ADD
    if (this._handshakeDone) return;
    if (!this._conn || this._finished) return;
    this._handshakeDone = true;
    console.log('[Sync] Handshake — role:', this._role, 'mode:', this._mode);
    this._progress({ phase: 'connected', message: 'Devices connected.' });
    if (this._role === 'host') this._hostFlow();
    else                        this._guestFlow();
  };

  if (conn.open) {
    setTimeout(doHandshake, 0);
  } else {
    conn.on('open', doHandshake);
  }

  conn.on('data', (data) => {                                  // ← CHANGED
    if (!alive() || this._conn !== conn) return;
    this._handleMessage(data);
  });

  conn.on('error', (err) => {                                  // ← CHANGED
    if (!alive() || this._conn !== conn) return;
    console.error('[Sync] Connection error:', err);
    this._fail('Connection error: ' + (err.message || 'unknown'));
  });

  conn.on('close', () => {                                     // ← CHANGED
    if (!alive() || this._conn !== conn) return;
    console.log('[Sync] Data channel closed.');
    if (this._recvDone && !this._finished) {
      this._cancelSenderAckWait();
      this._progress({ phase: 'done', message: 'Sync complete.', percent: 100 });
      this._finish({ success: true });
    }
  });
},

  /* ========================================================================
     HOST FLOW — build snapshot, wait for the receiver, send
     ======================================================================== */
  async _hostFlow() {
    if (this._mode === 'send') {
      this._progress({ phase: 'preparing', message: 'Building snapshot…' });
      try {
        this._snapshot = await this._buildSnapshot();
      } catch (e) {
        this._fail('Could not read local data: ' + (e.message || ''));
        return;
      }
      console.log('[Sync] Host snapshot built.');
      // Do NOT send yet — wait for the receiver's ready signal.
      this._progress({ phase: 'waiting-data', message: 'Waiting for the receiving device…' });
      this._maybeSendSnapshot();
    } else {
      // Host is the receiver in this scenario.
      this._progress({ phase: 'waiting-data', message: 'Waiting for the other device to send…' });
      this._sendMessage({ type: 'ready-to-receive' });
    }
  },

  /* ========================================================================
     GUEST FLOW
     ======================================================================== */
async _guestFlow() {
    const myToken = this._sessionToken;                    // ← ADD
    const alive = () => this._sessionToken === myToken;    // ← ADD

    // Defensive: if this method was invoked with no active session,
    // there is nothing to do. (Should not happen in normal flow.)
    if (!myToken) return;                                  // ← ADD

    if (this._mode === 'receive') {
      if (!alive()) return;                                // ← ADD
      this._progress({ phase: 'waiting-data', message: 'Waiting for data…' });
      this._sendMessage({ type: 'ready-to-receive' });

      // Watchdog — catches two distinct failure modes:
      //   (a) the sender never starts sending at all
      //   (b) the sender dies mid-transfer, after meta but before 'snapshot-done'
      // It is deliberately NOT cleared when 'snapshot-meta' arrives — it must
      // keep running through the whole transfer. It is only cleared on the
      // successful 'snapshot-done' path (or on _fail/_finish via close()).
      this._lastMetaAt = Date.now();
      if (this._recvWatchdog) clearInterval(this._recvWatchdog);
      this._recvWatchdog = setInterval(() => {
        if (!alive()) {                                    // ← ADD
          clearInterval(this._recvWatchdog);
          this._recvWatchdog = null;
          return;
        }
        if (!this._handshakeDone) return;
        if (this._recvDone) {           // transfer already completed — stop polling
          clearInterval(this._recvWatchdog);
          this._recvWatchdog = null;
          return;
        }

        const silentFor = Date.now() - this._lastMetaAt;

        // (a) No metadata at all in 45 s → the sender never began.
        if (!this._recvTotal && silentFor > 45000) {
          clearInterval(this._recvWatchdog);
          this._recvWatchdog = null;
          this._fail('The other device accepted the connection but sent no data. Try again.');
          return;
        }

        // (b) Metadata arrived but nothing has moved in 45 s → sender dropped.
        if (this._recvTotal && silentFor > 45000) {
          clearInterval(this._recvWatchdog);
          this._recvWatchdog = null;
          this._fail('The other device stopped sending data. Nothing was changed on this device.');
          return;
        }
      }, 5000);
    } else {
      // Guest is the sender.
      this._progress({ phase: 'preparing', message: 'Building snapshot…' });
      try {
        this._snapshot = await this._buildSnapshot();
      } catch (e) {
        this._fail('Could not read local data: ' + (e.message || ''));
        return;
      }
      if (!alive()) return;                                // ← ADD
      this._progress({ phase: 'waiting-data', message: 'Waiting for the receiving device…' });
      this._maybeSendSnapshot();
    }
  },

  /* ========================================================================
     SEND GATE — the single place where a snapshot may leave the device
     ======================================================================== */
  _maybeSendSnapshot() {
    if (this._sent) return;
    if (!this._snapshot) return;
    if (!this._guestReady) return;   // still waiting for the receiver's signal
    this._sent = true;
    console.log('[Sync] All conditions met — sending snapshot.');
    this._progress({ phase: 'sending', message: 'Sending data…', percent: 0 });
    this._sendChunkedSnapshot(this._snapshot);
  },

  /* ========================================================================
     SNAPSHOT BUILDER — same shape as Pages.backupAll
     ======================================================================== */
  async _buildSnapshot() {
    const data = {
      application: CONFIG.APP_NAME,
      version: CONFIG.VERSION,
      formatVersion: 2,
      exportDate: new Date().toISOString(),
      database: { name: CONFIG.DB_NAME, version: CONFIG.DB_VERSION, stores: CONFIG.STORES.slice() },
      data: {},
      counts: {}
    };
    await DB.open();
    for (const store of CONFIG.STORES) {
      let rows = await DB.getAll(store);
      if (!Array.isArray(rows)) throw new Error('Could not read store: ' + store);

      // Never transmit credentials, API keys, license records, or device-local
      // UI state. The receiving device keeps its own copy of these — see
      // `_applySnapshot`, which re-injects them into the incoming payload.
      if (store === 'settings') {
        rows = rows.filter(r => {
          if (typeof r.id !== 'string') return true;
          if (r.id.startsWith('imgCache.')) return false;
          if (this.SENSITIVE_SETTING_KEYS.has(r.id)) return false;
          return true;
        });
      }

      data.data[store] = rows;
      data.counts[store] = rows.length;
    }
    return data;
  },

  /* ========================================================================
     CHUNKED SEND
     ======================================================================== */
  /**
   * Sends a message over the data channel.
   * Returns true on success, false if the channel was closed or the send
   * threw. Callers on the critical chunk path MUST check the return value —
   * silently dropping a chunk produces an un-parseable snapshot on the far
   * side and wastes the user's time.
   */
  _sendMessage(msg) {
    if (!this._conn || !this._conn.open) {
      console.warn('[Sync] Attempted to send while channel is closed:', msg && msg.type);
      return false;
    }
    try {
      this._conn.send(msg);
      return true;
    } catch (e) {
      console.warn('[Sync] send failed:', e);
      return false;
    }
  },

_sendChunkedSnapshot(snapshot) {
    const sessionToken = this._sessionToken;                     // ← ADD
    const alive = () => this._sessionToken === sessionToken;     // ← ADD

    const json = JSON.stringify(snapshot);
    const CHUNK = 16 * 1024;                    // 16 KB — safe across browsers
    const totalChunks = Math.ceil(json.length / CHUNK);
    this._sendSize = json.length;
    this._sendSent = 0;
    console.log('[Sync] Snapshot size:', json.length, 'bytes; chunks:', totalChunks);

    if (!this._sendMessage({
      type: 'snapshot-meta',
      totalChunks,
      totalSize: json.length,
      exportDate: snapshot.exportDate,
      appVersion: snapshot.version
    })) {
      this._fail('Could not open the data channel. Please try again.');
      return;
    }

    let i = 0;
    const pump = () => {
      if (!alive()) return;   
      if (!this._conn || !this._conn.open) {
        // Channel closed mid-transfer — surface the failure rather than
        // leaving the sender's modal stuck forever.
        this._fail('The connection to the other device was lost during transfer. Nothing was changed on either side.');
        return;
      }

      // If the channel is buffering, wait for it to drain before pushing more.
      const buffered = this._conn.dataChannel
        ? this._conn.dataChannel.bufferedAmount
        : 0;
      if (buffered > 512 * 1024) {
        setTimeout(pump, 40);
        return;
      }

      if (i >= totalChunks) {
        if (!this._sendMessage({ type: 'snapshot-done' })) {
          this._fail('Could not finalise the transfer. Please try again.');
          return;
        }

        // ── Sender-side ack watchdog ──
        // The receiver will reply with `applied` or `apply-failed`. If we
        // don't hear back within 15 s (receiver crashed, ICE died after the
        // last chunk, tab closed), still close out the modal — the data was
        // sent. Flag the result as unconfirmed so the sender's UI can warn
        // the user to verify on the other device.
        if (this._ackWatchdog) clearTimeout(this._ackWatchdog);
        this._ackWatchdog = setTimeout(() => {
          if (!alive()) return;
          this._ackWatchdog = null;
          console.warn('[Sync] Sender did not receive receiver confirmation in time.');
          this._progress({
            phase: 'done',
            message: 'Transfer sent — the other device did not confirm in time. Please verify on that device.',
            percent: 100,
            unconfirmed: true
          });
          this._finish({ success: true, unconfirmed: true });
        }, 15000);

        this._progress({ phase: 'sent', message: 'Transfer complete. Waiting for confirmation…', percent: 100 });
        console.log('[Sync] All chunks sent. Awaiting confirmation.');
        return;
      }

      const chunk = json.slice(i * CHUNK, (i + 1) * CHUNK);
      if (!this._sendMessage({ type: 'snapshot-chunk', index: i, chunk })) {
        if (this._ackWatchdog) { clearTimeout(this._ackWatchdog); this._ackWatchdog = null; }
        this._fail('Data channel dropped mid-transfer. Nothing was changed on either side.');
        return;
      }
      this._sendSent += chunk.length;
      i++;

      const pct = Math.round((this._sendSent / this._sendSize) * 100);
      this._progress({ phase: 'sending', message: 'Sending data…', percent: pct });

      setTimeout(pump, 0);
    };
    pump();
  },

  /* ========================================================================
     MESSAGE HANDLER
     ======================================================================== */
  async _handleMessage(data) {
    if (!data || typeof data !== 'object') return;

    switch (data.type) {

      case 'ready-to-receive':
        // The receiver is ready. If we hold the snapshot, send it (once).
        this._guestReady = true;
        this._maybeSendSnapshot();
        break;

      case 'ready-to-send':
        // Other side says it will send — reply that we're ready.
        this._sendMessage({ type: 'ready-to-receive' });
        break;

      case 'snapshot-meta':
        this._recvChunks = new Array(data.totalChunks);
        this._recvTotal = data.totalChunks;
        this._recvSize = data.totalSize;
        this._lastMetaAt = Date.now();
        // Deliberately do NOT clear _recvWatchdog — it must keep running so
        // it can catch a sender that dies mid-transfer.
        console.log('[Sync] Receiving snapshot —', data.totalChunks, 'chunks;', data.totalSize, 'bytes.');
        this._progress({ phase: 'receiving', message: 'Receiving data…', percent: 0 });
        break;

      case 'snapshot-chunk': {
        if (!Array.isArray(this._recvChunks)) return;
        this._recvChunks[data.index] = data.chunk;
        this._lastMetaAt = Date.now();   // feed the watchdog on every frame

        let received = 0;
        for (let i = 0; i < this._recvChunks.length; i++) {
          if (typeof this._recvChunks[i] === 'string') received += this._recvChunks[i].length;
        }
        const pct = this._recvSize ? Math.round((received / this._recvSize) * 100) : 0;
        this._progress({ phase: 'receiving', message: 'Receiving data…', percent: pct });
        break;
      }

      case 'snapshot-done': {
        console.log('[Sync] All chunks received. Reassembling…');

        this._recvDone = true;
        if (this._recvWatchdog) { clearInterval(this._recvWatchdog); this._recvWatchdog = null; }

        this._progress({ phase: 'applying', message: 'Applying received data…', percent: 100 });

        // ── Missing-chunk check ──
        // A dropped chunk becomes `undefined`. Detect it BEFORE the join,
        // so we can ask the sender to retry the whole transfer instead of
        // handing garbage to JSON.parse.
        const missing = [];
        for (let i = 0; i < this._recvTotal; i++) {
          if (typeof this._recvChunks[i] !== 'string') missing.push(i);
        }
        if (missing.length) {
          console.error('[Sync] Missing chunks:', missing);
          this._sendMessage({
            type: 'apply-failed',
            reason: `Transfer incomplete — ${missing.length} packet${missing.length === 1 ? '' : 's'} lost.`
          });
          this._fail(
            `The transfer was incomplete (${missing.length} of ${this._recvTotal} packets lost). ` +
            `Nothing was changed on this device. Please try again on a more stable connection.`
          );
          return;
        }

        // ── Reassemble ──
        let snapshot;
        try {
          const json = this._recvChunks.join('');
          if (json.length !== this._recvSize) {
            throw new Error(`Size mismatch — expected ${this._recvSize} bytes, got ${json.length}.`);
          }
          snapshot = JSON.parse(json);
        } catch (e) {
          console.error('[Sync] Reassembly failed:', e);
          this._sendMessage({ type: 'apply-failed', reason: 'Snapshot could not be parsed.' });
          this._fail('The received data was corrupted. Nothing was changed on this device.');
          return;
        }

        // ── Validate shape before touching the DB ──
        if (!snapshot || snapshot.application !== CONFIG.APP_NAME ||
            !snapshot.data || typeof snapshot.data !== 'object') {
          this._sendMessage({ type: 'apply-failed', reason: 'Not a valid KlazAssist snapshot.' });
          this._fail('The other device sent data that is not a valid KlazAssist snapshot.');
          return;
        }

        this._recvChunks = null;   // free memory before the DB write

        // ── Apply ──
        try {
          await this._applySnapshot(snapshot);
        } catch (e) {
          console.error('[Sync] Apply failed:', e);
          this._sendMessage({ type: 'apply-failed', reason: e.message || 'Apply failed.' });
          this._fail('Could not apply the received data: ' + (e.message || 'unknown error'));
          return;
        }

        // ── Confirm to sender, then finish ──
        this._sendMessage({ type: 'applied' });
        this._progress({ phase: 'done', message: 'Sync complete.', percent: 100 });
        this._finish({ success: true });
        break;
      }

      case 'applied':
        // Sender path: the receiver has confirmed the write.
        this._cancelSenderAckWait();
        this._finish({ success: true });
        break;

      case 'apply-failed':
        // Sender path: receiver could not write the data.
        this._cancelSenderAckWait();
        this._fail(
          'The other device could not save the data: ' +
          (data.reason || 'unknown reason') +
          ' Nothing was changed on either side.'
        );
        break;

      case 'cancel':
        this._fail('The other device cancelled the sync.');
        break;

      default:
        console.warn('[Sync] Unknown message type:', data.type);
    }
  },

  /* ========================================================================
     APPLY SNAPSHOT
     ------------------------------------------------------------------------
     Writes the incoming data into IndexedDB, preserving the receiving
     device's own credentials and API keys. Uses the same atomic bulk-write
     path as `DB.restoreSnapshot`, so a mid-transfer failure leaves the
     receiving database untouched.
     ======================================================================== */
  async _applySnapshot(snapshot) {
    // Re-inject this device's sensitive settings, which the sender filtered
    // out. We read them locally and merge them back into the incoming
    // `settings` store so a sync never wipes the receiver's login.
    const preserved = [];
    for (const key of this.SENSITIVE_SETTING_KEYS) {
      try {
        const rec = await DB.get('settings', key);
        if (rec) preserved.push(rec);
      } catch (e) {}
    }

    // Normalise the payload: every store guaranteed to be an array, and
    // unknown stores dropped (defends against a future-version sender).
    const incoming = snapshot && snapshot.data;
    if (!incoming || typeof incoming !== 'object' || Array.isArray(incoming)) {
      throw new Error('The received sync snapshot is invalid. No data was changed.');
    }
    // Keep absent stores absent. DB.restoreSnapshot interprets absence as
    // "preserve local store"; fabricating [] here would erase newer local data.
    const normalised = {};
    for (const store of CONFIG.STORES) {
      if (!Object.prototype.hasOwnProperty.call(incoming, store)) continue;
      if (!Array.isArray(incoming[store])) {
        throw new Error(`The received sync data for "${store}" is invalid. No data was changed.`);
      }
      normalised[store] = incoming[store];
    }

    // Preserve this device's sensitive settings. If the sender omitted the
    // settings store entirely, retain all local settings rather than creating
    // a partial replacement store.
    if (Object.prototype.hasOwnProperty.call(normalised, 'settings') && preserved.length) {
      const existing = new Map(normalised.settings.map(r => [r.id, r]));
      preserved.forEach(r => existing.set(r.id, r));
      normalised.settings = Array.from(existing.values());
    }

    // Atomic write — all stores or none.
    await DB.restoreSnapshot(
      { data: normalised, exportDate: snapshot.exportDate, formatVersion: snapshot.formatVersion },
      { replace: true, beforeReplace: () => Pages._downloadRecoveryBackup('before-sync') }
    );

    // Refresh in-memory account & license from the now-updated settings store.
    try {
      Auth._account = null;
      await Auth.load();
      if (Auth._account) Auth._writeShadow(Auth._account);
      Licensing._license = null;
      await Licensing.init();
    } catch (e) {
      console.warn('[Sync] Post-apply account refresh failed:', e);
    }

    await App.loadState();
  },

  /* ========================================================================
     CLEANUP / STATUS HELPERS
     ======================================================================== */
  _cancelSenderAckWait() {
    if (this._ackWatchdog) { clearTimeout(this._ackWatchdog); this._ackWatchdog = null; }
  },

  _progress(p) {
    if (typeof this._onProgress === 'function') {
      try { this._onProgress(p); } catch (e) { console.warn('[Sync] progress handler threw:', e); }
    }
  },

  _finish(result) {
    if (this._finished) return;
    this._finished = true;
    if (typeof this._onComplete === 'function') {
      try { this._onComplete(result); } catch (e) { console.warn('[Sync] complete handler threw:', e); }
    }
    // Give the peer ~2 s so it can close cleanly, then tear down.
    setTimeout(() => this.close(), 2000);
  },

  _fail(msg) {
    if (this._finished) return;
    this._finished = true;
    if (typeof this._onError === 'function') {
      try { this._onError(msg); } catch (e) { console.warn('[Sync] error handler threw:', e); }
    }
    setTimeout(() => this.close(), 2000);
  },

  close() {
    // Invalidate the session token FIRST so any in-flight async callback
    // (ICE watchers, retry timers, chunk pumps) short-circuits immediately.
    this._sessionToken = null;

    if (this._recvWatchdog) { clearInterval(this._recvWatchdog); this._recvWatchdog = null; }
    if (this._ackWatchdog)  { clearTimeout(this._ackWatchdog);  this._ackWatchdog  = null; }
    if (this._stopHostIce)  { try { this._stopHostIce(); } catch (e) {} this._stopHostIce = null; }

    try { if (this._conn) this._conn.close(); } catch (e) {}
    try { if (this._peer) this._peer.destroy(); } catch (e) {}

    this._peer = null;
    this._conn = null;
    this._snapshot = null;
    this._recvChunks = null;
    this._recvTotal = 0;
    this._recvSize = 0;
    this._sendSize = 0;
    this._sendSent = 0;
    this._guestReady = false;
    this._sent = false;
    this._handshakeDone = false;
    this._recvDone = false;
    this._finished = false;
    this._timedOut = false;
    this._guestConnecting = false;
    this._retryCount = 0;
    this._lastMetaAt = 0;
  },

  /* ========================================================================
     DIAGNOSTIC — from the DevTools console:  SyncManager.diagnose()
     ======================================================================== */
  async diagnose() {
    const rows = [];
    rows.push(['PeerJS loaded',   !!this._peerCtor()]);
    rows.push(['Browser WebRTC',  !!(window.RTCPeerConnection)]);
    rows.push(['Data channels',   !!(window.RTCPeerConnection && 'createDataChannel' in RTCPeerConnection.prototype)]);
    rows.push(['Secure context',  window.isSecureContext]);
    rows.push(['Online',          navigator.onLine]);

    const ice = this._readJsonSetting('klaz.sync.iceServers');
    rows.push(['Custom ICE',      ice ? `${Array.isArray(ice) ? ice.length : '?'} entries` : 'none']);
    const srv = this._readJsonSetting('klaz.sync.peerServer');
    rows.push(['Custom peer srv', srv && srv.host ? srv.host : 'PeerJS cloud']);

    console.table(rows.reduce((acc, [k, v]) => { acc[k] = v; return acc; }, {}));
    return rows;
  }
};

/* ============================================================================
   UNSAVED-CHANGES GUARD + DRAFT RECOVERY
   ----------------------------------------------------------------------------
   • Any module can mark itself dirty:   Unsaved.mark('lesson-planner')
   • Any module can mark itself clean:   Unsaved.clear('lesson-planner')
   • On navigation away, a dirty module gets a three-way prompt:
        Save draft  ·  Discard  ·  Stay here
   • Drafts survive reloads and can be re-opened from a floating badge.
   ============================================================================ */
const Unsaved = {
  _dirty: new Set(),
  _drafts: new Map(),
  _handlers: new Map(),
  _labels:   new Map(),
  _restorers: new Map(),
  _draftKey: 'klazassist.unsavedDrafts',

register(moduleId, label, handler) {
  this._labels.set(moduleId, label);
  if (typeof handler === 'function') this._handlers.set(moduleId, handler);
  this._loadPersisted();
  this._reflectBadge();   // ← keep the floating badge in sync with the
                          //   in-memory draft map every time a module
                          //   registers a new producer.
},

  registerRestorer(moduleId, fn) {
    this._restorers.set(moduleId, fn);
  },

  mark(moduleId) {
    if (!moduleId) return;
    this._dirty.add(moduleId);
    this._reflectBadge();
  },

  clear(moduleId) {
    this._dirty.delete(moduleId);
    this._drafts.delete(moduleId);
    this._persist();
    this._reflectBadge();
  },

  isDirty() { return this._dirty.size > 0; },

async intercept(targetModuleId) {
  const blockers = Array.from(this._dirty).filter(id => id !== targetModuleId);
  if (!blockers.length) return { action: 'proceed' };

  const label = blockers.length === 1
    ? (this._labels.get(blockers[0]) || 'this page')
    : `${blockers.length} pages`;

  const choice = await new Promise(resolve => {
    // Guard against double-settle. UI.modal's close() calls onClose()
    // synchronously, and the button handlers also close the modal — without
    // this flag, whichever runs first wins, and onClose always wins because
    // it fires inside m.close() before our resolve() line executes.
    let settled = false;
    const finish = (v) => {
      if (settled) return;
      settled = true;
      resolve(v);
      try { m.close(); } catch (e) {}
    };

    const m = UI.modal({
      title: 'You have unsaved changes',
      body: `
        <div class="alert alert-warning mb-16">${icon('alert')}<div>
          <strong>${Utils.esc(label)}</strong> ${blockers.length === 1 ? 'has' : 'have'}
          edits that haven't been saved yet.
        </div></div>
        <p class="text-sm text-muted" style="line-height:1.65;">
          You can save a draft (kept on this device and restorable any time),
          discard the changes, or stay on the current page.
        </p>`,
      footer: `
        <button class="btn btn-outline" id="un-stay">Stay here</button>
        <button class="btn btn-ghost"   id="un-discard">Discard</button>
        <button class="btn btn-primary" id="un-save">Save draft</button>`,
      onClose: () => finish({ action: 'cancel' })
    });

    m.overlay.querySelector('#un-stay').onclick    = () => finish({ action: 'cancel' });
    m.overlay.querySelector('#un-discard').onclick = () => finish({ action: 'proceed', discard: true });
    m.overlay.querySelector('#un-save').onclick    = () => finish({ action: 'proceed', save: true });
  });

  if (choice.action === 'cancel') return choice;

if (choice.save) {
  let savedCount = 0;

  for (const id of blockers) {
    const producer = this._handlers.get(id);
    const payload = producer ? producer() : null;

    if (payload) {
      this._drafts.set(id, {
        savedAt: new Date().toISOString(),
        payload,
        label: this._labels.get(id) || id
      });
      savedCount++;
    } else {
      // Producer returned nothing — either the form is already gone
      // or the teacher hadn't filled in the mandatory fields. Surface
      // it so the empty badge result is never a mystery.
      console.warn('[Unsaved] No draft captured for module:', id);
    }
  }

  const persisted = this._persist();
  this._reflectBadge();

  if (savedCount > 0 && persisted) {
    UI.toast('Draft saved. Click the drafts badge to restore it.', 'success', 3500);
  } else if (savedCount > 0 && !persisted) {
    UI.toast('Draft captured for this session, but browser storage failed. Export or copy your work before leaving.', 'warning', 5000);
  } else {
    UI.toast('Nothing to save — no unsaved form data was found.', 'warning', 3500);
  }
}

  // Close any lingering form modal (e.g. the Lesson Plan editor) so it
  // does not float on top of the page we are navigating to.
  document.querySelectorAll('.modal-overlay').forEach(el => el.remove());

  for (const id of blockers) this._dirty.delete(id);
  this._reflectBadge();
  return { action: 'proceed' };
},

  peek(moduleId) {
    return this._drafts.get(moduleId) || null;
  },

  _persist() {
    try {
      const out = {};
      for (const [id, d] of this._drafts) {
        let json;
        try { json = JSON.stringify(d.payload); } catch (e) { continue; }
        if (json.length > 200 * 1024) continue;
        out[id] = { savedAt: d.savedAt, label: d.label, payload: d.payload };
      }
      localStorage.setItem(this._draftKey, JSON.stringify(out));
      return true;
    } catch (e) {
      console.warn('[Unsaved] Could not persist drafts to localStorage:', e);
      return false;
    }
  },

  _loadPersisted() {
    // Rebuild the map from storage rather than merging stale in-memory entries.
    try {
      const raw = localStorage.getItem(this._draftKey);
      if (!raw) {
        this._drafts.clear();
        return;
      }
      const parsed = JSON.parse(raw);
      this._drafts.clear();
      if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return;
      for (const [id, d] of Object.entries(parsed)) {
        if (d && Object.prototype.hasOwnProperty.call(d, 'payload') && d.savedAt) {
          this._drafts.set(id, d);
        }
      }
    } catch (e) {
      console.warn('[Unsaved] Could not load persisted drafts:', e);
    }
  },

  _reflectBadge() {
    let badge = document.getElementById('unsaved-badge');
    const n = this._drafts.size;
    if (n === 0) { if (badge) badge.remove(); return; }

    // Always attach the badge directly to <body> and explicitly restore its
    // visible state. This also repairs a badge left hidden by another UI flow.
    if (!badge) {
      badge = document.createElement('button');
      badge.id = 'unsaved-badge';
      badge.type = 'button';
      badge.className = 'unsaved-badge';
      badge.setAttribute('aria-label', 'Restore a saved draft');
      badge.onclick = () => this.openDraftsPanel();
      document.body.appendChild(badge);
    } else if (badge.parentElement !== document.body) {
      document.body.appendChild(badge);
    }
    badge.hidden = false;
    badge.removeAttribute('hidden');
    badge.style.setProperty('display', 'flex', 'important');
    badge.style.setProperty('visibility', 'visible', 'important');
    badge.style.setProperty('opacity', '1', 'important');
    badge.style.setProperty('pointer-events', 'auto', 'important');
    badge.style.setProperty('z-index', '10060', 'important');
    badge.innerHTML = `${icon('save')}<span>${n}</span>`;
    badge.title = `${n} saved draft${n === 1 ? '' : 's'} — click to restore`;
  },

  openDraftsPanel() {
    const rows = Array.from(this._drafts.entries())
      .sort((a, b) => (b[1].savedAt || '').localeCompare(a[1].savedAt || ''));

    const m = UI.modal({
      title: 'Saved drafts',
      size: 'modal-lg',
      body: rows.length ? `
        <p class="text-sm text-muted mb-12">
          Drafts are stored on this device only. They are not uploaded anywhere.
        </p>
        <div class="unsaved-draft-list">
          ${rows.map(([id, d]) => `
            <div class="unsaved-draft-row" data-draft-id="${Utils.attr(id)}">
              <div class="unsaved-draft-main">
                <div class="unsaved-draft-label">${Utils.esc(d.label || id)}</div>
                <div class="unsaved-draft-meta">Saved ${Utils.timeAgo(d.savedAt)}</div>
              </div>
              <div class="unsaved-draft-actions">
                <button class="btn btn-sm btn-outline" data-draft-restore="${Utils.attr(id)}">
                  ${icon('history')} Restore
                </button>
                <button class="btn btn-sm btn-ghost" data-draft-delete="${Utils.attr(id)}"
                        style="color:var(--danger);">
                  ${icon('trash')}
                </button>
              </div>
            </div>`).join('')}
        </div>` : `<p class="text-sm text-muted">No saved drafts.</p>`,
      footer: `<button class="btn btn-primary" data-close>Close</button>`
    });

    m.overlay.querySelectorAll('[data-draft-restore]').forEach(btn => {
      btn.onclick = async () => {
        const id = btn.dataset.draftRestore;
        const d = this._drafts.get(id);
        if (!d) return;
        m.close();
        await this._restore(id, d.payload);
      };
    });

    m.overlay.querySelectorAll('[data-draft-delete]').forEach(btn => {
      btn.onclick = () => {
        const id = btn.dataset.draftDelete;
        this._drafts.delete(id);
        this._persist();
        this._reflectBadge();
        m.close();
        this.openDraftsPanel();
      };
    });
  },

  /* Opens a modal, waits for it to settle, then returns a small "apply"
     function that writes values into the modal's fields. Every restorer
     that lives on top of a UI.modal ends up needing this. */
  async _prefillModal(openFn, delayMs = 80) {
    await openFn();
    await new Promise(r => setTimeout(r, delayMs));
    const ov = document.querySelector('.modal-overlay.show');
    if (!ov) return null;
    return {
      overlay: ov,
      set(sel, v) {
        const el = ov.querySelector(sel);
        if (el && v !== undefined && v !== null) el.value = v;
      },
      check(sel, on) {
        const el = ov.querySelector(sel);
        if (el) el.checked = !!on;
      },
      click(sel) {
        const el = ov.querySelector(sel);
        if (el) el.click();
      }
    };
  },

  async _restore(moduleId, payload) {   
    const restorer = this._restorers.get(moduleId);
    if (restorer) {
      try {
        await restorer(payload);
        // Do NOT delete the draft here. The restorer only re-opens the
        // editor with the draft's values — the teacher still has to click
        // Save. If they cancel, the draft must remain available for a
        // second attempt. The module's own save handler calls
        // Unsaved.clear(id), which is what actually removes the draft.
        this._reflectBadge();
        UI.toast('Draft restored — remember to save.', 'success', 3500);
        return;
      } catch (e) {
        console.error('[Unsaved] restore handler threw:', e);
        UI.toast('Could not restore the draft.', 'error');
        return;
      }
    }
    try {
      Utils.download(
        `klazassist-draft-${moduleId}-${Utils.timestampForFilename()}.json`,
        JSON.stringify(payload, null, 2),
        'application/json'
      );
      UI.toast('Draft downloaded as JSON (no inline restore available for this module).', 'info', 5000);
    } catch (e) {
      UI.toast('Could not restore or download the draft.', 'error');
    }
  }
};

/* -------- Hook into App.navigate -------- */
const _origNavigate = App.navigate.bind(App);
App.navigate = async function (id) {
  if (id === State.currentModule) return _origNavigate(id);
  const verdict = await Unsaved.intercept(id);
  if (verdict.action === 'cancel') return;
  return _origNavigate(id);
};

/* -------- Warn before tab close -------- */
window.addEventListener('beforeunload', (e) => {
  if (Unsaved.isDirty()) {
    e.preventDefault();
    e.returnValue = '';
  }
});


/* ============================================================================
   KEYBOARD SHORTCUTS
   ----------------------------------------------------------------------------
   • "G then X" chord navigation — no modifier required.
   • Cmd/Ctrl+K opens the existing global search.
   • Shift+? opens a shortcuts cheat sheet.
   • Never fires while a text field has focus.
   ============================================================================ */
const Shortcuts = {
  _chordArmed: false,
  _chordTimer: null,

  BINDINGS: [
    { chord: 'd', label: 'Go to Dashboard',        run: () => App.navigate('dashboard') },
    { chord: 'a', label: 'Go to Attendance',       run: () => App.navigate('attendance') },
    { chord: 'l', label: 'Go to Learners',         run: () => App.navigate('learners') },
    { chord: 'g', label: 'Go to Gradebook',        run: () => App.navigate('gradebook') },
    { chord: 's', label: 'Go to Schedule',         run: () => App.navigate('schedule') },
    { chord: 'p', label: 'Go to Lesson Planner',   run: () => App.navigate('lesson-planner') },
    { chord: 't', label: 'Go to Teaching Tools',   run: () => App.navigate('teaching-tools') },
    { chord: 'f', label: 'Go to School Forms',     run: () => App.navigate('school-forms') },
    { chord: 'n', label: 'Go to Notes',            run: () => App.navigate('notes') },
    { chord: 'r', label: 'Go to Reports & Export', run: () => App.navigate('reports-and-export') }
  ],

  init() {
    document.addEventListener('keydown', (e) => this._onKey(e));
  },

  _inTextInput(el) {
    if (!el) return false;
    const tag = (el.tagName || '').toLowerCase();
    if (tag === 'input' || tag === 'textarea' || tag === 'select') return true;
    if (el.isContentEditable) return true;
    return false;
  },

  _onKey(e) {
    const focused = document.activeElement;
    const typing = this._inTextInput(focused);

    if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'k') {
      e.preventDefault();
      if (Session.state.authenticated && !Session.state.locked) App.openGlobalSearch();
      return;
    }

    if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 's') {
      e.preventDefault();
      document.dispatchEvent(new CustomEvent('klaz:save-shortcut'));
      return;
    }

    if (!typing && e.key === '?') {
      e.preventDefault();
      this.showCheatsheet();
      return;
    }

    if (typing) return;
    if (e.ctrlKey || e.metaKey || e.altKey) return;
    if (!Session.state.authenticated || Session.state.locked) return;

    if (e.key.toLowerCase() === 'g') {
      this._chordArmed = true;
      if (this._chordTimer) clearTimeout(this._chordTimer);
      this._chordTimer = setTimeout(() => { this._chordArmed = false; }, 1400);
      return;
    }

    if (this._chordArmed) {
      const key = e.key.toLowerCase();
      const match = this.BINDINGS.find(b => b.chord === key);
      this._chordArmed = false;
      if (this._chordTimer) { clearTimeout(this._chordTimer); this._chordTimer = null; }
      if (match) {
        e.preventDefault();
        match.run();
      }
    }
  },

  showCheatsheet() {
    const modKey = navigator.platform && /Mac/i.test(navigator.platform) ? '⌘' : 'Ctrl';
    UI.modal({
      title: 'Keyboard shortcuts',
      size: 'modal-lg',
      body: `
        <p class="text-sm text-muted mb-16">
          Press <kbd>G</kbd> then a second key to jump anywhere. Shortcuts
          are disabled while you're typing in a text field.
        </p>

        <div class="shortcut-section">Navigation — <kbd>G</kbd> then…</div>
        <div class="shortcut-grid">
          ${this.BINDINGS.map(b => `
            <div class="shortcut-row">
              <span class="shortcut-keys">
                <kbd>G</kbd> <span class="shortcut-plus">then</span> <kbd>${b.chord.toUpperCase()}</kbd>
              </span>
              <span class="shortcut-label">${Utils.esc(b.label.replace('Go to ', ''))}</span>
            </div>`).join('')}
        </div>

        <div class="shortcut-section">Anywhere</div>
        <div class="shortcut-grid">
          <div class="shortcut-row">
            <span class="shortcut-keys"><kbd>${modKey}</kbd> <kbd>K</kbd></span>
            <span class="shortcut-label">Global search</span>
          </div>
          <div class="shortcut-row">
            <span class="shortcut-keys"><kbd>${modKey}</kbd> <kbd>S</kbd></span>
            <span class="shortcut-label">Save current form</span>
          </div>
          <div class="shortcut-row">
            <span class="shortcut-keys"><kbd>Shift</kbd> <kbd>?</kbd></span>
            <span class="shortcut-label">Show this cheatsheet</span>
          </div>
          <div class="shortcut-row">
            <span class="shortcut-keys"><kbd>Esc</kbd></span>
            <span class="shortcut-label">Close the top dialog</span>
          </div>
        </div>`,
      footer: `<button class="btn btn-primary" data-close>Close</button>`
    });
  }
};
Shortcuts.init(); 


/* ============================================================================
   NETWORK STATUS INDICATOR
   ----------------------------------------------------------------------------
   A tiny pill in the topbar that reflects online / offline / syncing state.
   Offline is a first-class state in an offline-first app, so the pill turns
   blue instead of red — this is expected behaviour, not an error.
   ============================================================================ */
const NetStatus = {
  init() {
    if (!document.getElementById('net-pill-style')) {
      const s = document.createElement('style');
      s.id = 'net-pill-style';
      s.textContent = `
        .net-pill {
          display: inline-flex; align-items: center; gap: 6px;
          padding: 5px 10px; border-radius: 20px;
          font-size: 11px; font-weight: 700;
          background: rgba(25,135,84,0.10);
          color: var(--success);
          border: 1px solid rgba(25,135,84,0.22);
          transition: all 0.25s ease;
          white-space: nowrap;
        }
        .net-pill.offline {
          background: var(--light-blue);
          color: var(--deped-blue);
          border-color: rgba(0,56,168,0.22);
        }
        .net-pill.syncing {
          background: rgba(247,201,72,0.16);
          color: #8a6d0e;
          border-color: rgba(247,201,72,0.35);
        }
        .net-pill .net-dot {
          width: 7px; height: 7px; border-radius: 50%;
          background: currentColor;
        }
        .net-pill.syncing .net-dot { animation: netPulse 1.2s ease-in-out infinite; }
        @keyframes netPulse { 0%,100% { opacity: 1; } 50% { opacity: 0.35; } }
        @media (max-width: 640px) {
          .net-pill span.label { display: none; }
          .net-pill { padding: 5px 8px; }
        }
      `;
      document.head.appendChild(s);
    }

    const themeToggle = document.getElementById('theme-toggle');
    if (themeToggle && themeToggle.parentElement) {
      const pill = document.createElement('div');
      pill.id = 'net-pill';
      pill.className = 'net-pill';
      pill.innerHTML = `<span class="net-dot"></span><span class="label">Online</span>`;
      themeToggle.parentElement.insertBefore(pill, themeToggle);
    }

    const update = () => {
      const pill = document.getElementById('net-pill');
      if (!pill) return;
      const label = pill.querySelector('.label');
      pill.classList.remove('offline', 'syncing');
      if (!navigator.onLine) {
        pill.classList.add('offline');
        if (label) label.textContent = 'Offline';
        pill.title = 'Offline — all features still work. Sync and AI need internet.';
      } else {
        if (label) label.textContent = 'Online';
        pill.title = 'Connected. Sync and AI features are available.';
      }
    };

    window.addEventListener('online',  () => { update(); UI.toast('Back online', 'success', 2000); });
    window.addEventListener('offline', () => { update(); UI.toast('Offline — your work is still saved locally', 'info', 3500); });
    update();
    this._update = update;
  },

  setSyncing(on) {
    const pill = document.getElementById('net-pill');
    if (!pill) return;
    if (on) {
      pill.classList.remove('offline');
      pill.classList.add('syncing');
      const label = pill.querySelector('.label');
      if (label) label.textContent = 'Syncing…';
    } else {
      this._update && this._update();
    }
  }
};
window.SyncManager = SyncManager;

/* ============================================================================
   CLOUD BACKUP — Google Drive (appDataFolder)
   ----------------------------------------------------------------------------
   Stores JSON snapshots in the hidden appDataFolder of the teacher's own
   Google Drive. Uses the Google Identity Services token model:
     • OAuth consent popup returns a short-lived access token (~1 hour)
     • No refresh token — when the token expires, the user re-authorizes
     • Files are invisible in the Drive UI; only this OAuth client ID can
       see them
     • Files count against the teacher's own Drive quota (15 GB personal,
       100 GB Workspace for Education)

   The access token lives in memory only. If the page reloads, the user must
   re-authorize. This is deliberate: storing OAuth tokens in localStorage is
   a well-known XSS escalation vector.
   ============================================================================ */
const CloudBackup = {
  /* ---------- configuration ---------- */
  CLIENT_ID_KEY: 'cloudBackup.clientId',
  SCOPE: 'https://www.googleapis.com/auth/drive.appdata',
  FOLDER_LABEL: 'KlazAssist Backups',
  API_ROOT: 'https://www.googleapis.com/drive/v3',
  UPLOAD_ROOT: 'https://www.googleapis.com/upload/drive/v3',

  /* ---------- runtime state ---------- */
  _tokenClient: null,
  _accessToken: null,
  _tokenExpiresAt: 0,
  _connectedEmail: null,
  _pendingResolve: null,
  _pendingReject: null,

  /* ========================================================================
     LIBRARY LOADING
     ======================================================================== */
  async _ensureLib() {
    if (window.google && window.google.accounts && window.google.accounts.oauth2) {
      return true;
    }
    // The script is loaded in index.html with `async defer`. Wait for it.
    for (let i = 0; i < 80; i++) {         // up to 8 seconds
      if (window.google && window.google.accounts && window.google.accounts.oauth2) {
        return true;
      }
      await new Promise(r => setTimeout(r, 100));
    }
    throw new Error('Google Identity Services did not load. Check your internet connection.');
  },

  /* ========================================================================
     CLIENT ID MANAGEMENT
     ======================================================================== */
  async getClientId() {
    try {
      const saved = await DB.getSetting(this.CLIENT_ID_KEY, '');
      return String(saved || '').trim();
    } catch (e) {
      return '';
    }
  },

  async setClientId(id) {
    const clean = String(id || '').trim();
    // Google OAuth client IDs always end with .apps.googleusercontent.com
    if (clean && !/\.apps\.googleusercontent\.com$/.test(clean)) {
      throw new Error('That does not look like a Google OAuth client ID. It should end with ".apps.googleusercontent.com".');
    }
    await DB.setSetting(this.CLIENT_ID_KEY, clean);
    this._tokenClient = null;            // force re-init on next use
  },

  async isConfigured() {
    const id = await this.getClientId();
    return !!id;
  },

  /* ========================================================================
     AUTHENTICATION
     ======================================================================== */

  /** Initialise the GIS token client. Safe to call repeatedly. */
  async _ensureTokenClient() {
    await this._ensureLib();
    if (this._tokenClient) return this._tokenClient;

    const clientId = await this.getClientId();
    if (!clientId) {
      throw new Error('Google Drive backup is not configured. Set a client ID in Settings → Cloud Backup.');
    }

    const self = this;
    this._tokenClient = window.google.accounts.oauth2.initTokenClient({
      client_id: clientId,
      scope: this.SCOPE,
      callback: (response) => {
        // The GIS callback is global to the token client. We route it back
        // to whichever promise is currently waiting.
        if (!self._pendingResolve) return;

        if (response && response.error) {
          const rej = self._pendingReject;
          self._pendingResolve = null;
          self._pendingReject = null;
          if (rej) rej(new Error(response.error_description || response.error));
          return;
        }

        if (response && response.access_token) {
          self._accessToken = response.access_token;
          // expires_in is in seconds; subtract 60 s as a safety margin.
          const expiresIn = Number(response.expires_in) || 3600;
          self._tokenExpiresAt = Date.now() + (expiresIn - 60) * 1000;

          const res = self._pendingResolve;
          self._pendingResolve = null;
          self._pendingReject = null;
          if (res) res(self._accessToken);
        }
      },
      // Let the popup appear in the centre of the screen
      error_callback: (err) => {
        if (!self._pendingReject) return;
        const rej = self._pendingReject;
        self._pendingResolve = null;
        self._pendingReject = null;
        rej(new Error((err && (err.message || err.type)) || 'Authorization was cancelled.'));
      }
    });
    return this._tokenClient;
  },

  /**
   * Trigger the consent popup and return an access token.
   * If a valid token is already cached, returns it without a popup.
   *
   * @param {boolean} forceNew  When true, always show the popup even if
   *                            a cached token is still valid.
   */
  async connect(forceNew) {
    if (!forceNew && this._accessToken && Date.now() < this._tokenExpiresAt) {
      return this._accessToken;
    }

    const client = await this._ensureTokenClient();

    return new Promise((resolve, reject) => {
      this._pendingResolve = resolve;
      this._pendingReject  = reject;
      try {
        // "" reuses the user's last-granted scope; "consent" forces the
        // full consent screen. We use "" so returning users see the
        // faster flow.
        client.requestAccessToken({ prompt: forceNew ? 'consent' : '' });
      } catch (e) {
        this._pendingResolve = null;
        this._pendingReject = null;
        reject(e);
      }
    });
  },

  /** Revoke the current token and forget it. */
  async disconnect() {
    if (this._accessToken && window.google && window.google.accounts.oauth2) {
      try {
        window.google.accounts.oauth2.revoke(this._accessToken, () => {});
      } catch (e) { /* revoke is best-effort */ }
    }
    this._accessToken = null;
    this._tokenExpiresAt = 0;
    this._connectedEmail = null;
  },

  /** True when an access token is cached and not yet expired. */
  isConnected() {
    return !!(this._accessToken && Date.now() < this._tokenExpiresAt);
  },

  /* ========================================================================
     LOW-LEVEL API
     ======================================================================== */

  /**
   * Fetch wrapper that injects the Bearer token and transparently retries
   * once with a fresh token after a 401.
   */
  async _apiFetch(path, options = {}, _retried = false) {
    let token = this._accessToken;
    if (!token || Date.now() >= this._tokenExpiresAt) {
      token = await this.connect(false);
    }

    const headers = Object.assign({}, options.headers || {});
    headers['Authorization'] = 'Bearer ' + token;

    const res = await fetch(this.API_ROOT + path, Object.assign({}, options, { headers }));

    if (res.status === 401 && !_retried) {
      // Token was revoked or expired early — re-authorize and retry once.
      this._accessToken = null;
      this._tokenExpiresAt = 0;
      return this._apiFetch(path, options, true);
    }
    return res;
  },

  /* ========================================================================
     BACKUP LIST
     ======================================================================== */

  /**
   * List every backup file in the appDataFolder, newest first.
   * Returns [{ id, name, size, createdTime, modifiedTime }].
   */
  async listBackups() {
    const q = encodeURIComponent("name contains 'klazassist-backup' and trashed = false");
    const fields = encodeURIComponent('files(id,name,size,createdTime,modifiedTime)');
    const path = `/files?spaces=appDataFolder&q=${q}&fields=${fields}&orderBy=createdTime desc&pageSize=100`;

    const res = await this._apiFetch(path);
    if (!res.ok) {
      const err = await res.json().catch(() => ({}));
      throw new Error(err.error?.message || `Could not list backups (HTTP ${res.status})`);
    }
    const data = await res.json();
    return Array.isArray(data.files) ? data.files : [];
  },

  /* ========================================================================
     UPLOAD
     ======================================================================== */

  /**
   * Upload a backup snapshot to the appDataFolder.
   *
   * @param {Object} snapshot    The object produced by Pages.backupAll().
   * @param {Function} onProgress Optional callback({ loaded, total, percent }).
   * @returns {{ id, name, size }}
   */
  async upload(snapshot, onProgress) {
    if (!snapshot || !snapshot.data) {
      throw new Error('Nothing to upload — the backup snapshot is empty.');
    }

    const json   = JSON.stringify(snapshot);
    const blob   = new Blob([json], { type: 'application/json' });
    const size   = blob.size;

    // Guard against the 5 MB multipart limit. A full backup with photos is
    // usually 2–4 MB, but a very large school can exceed 5 MB.
    const FIVE_MB = 5 * 1024 * 1024;
    if (size > FIVE_MB) {
      throw new Error(
        `Backup is ${(size / 1024 / 1024).toFixed(1)} MB, which exceeds Google Drive's ` +
        `5 MB limit for this upload method. Try removing learner photos from the backup ` +
        `or wait for the resumable-upload feature.`
      );
    }

    const stamp = Utils.timestampForFilename();
    const name  = `klazassist-backup-${stamp}.json`;

    const metadata = {
      name,
      mimeType: 'application/json',
      parents: ['appDataFolder']
    };

    const form = new FormData();
    form.append('metadata',
      new Blob([JSON.stringify(metadata)], { type: 'application/json' }));
    form.append('file', blob);

    // The Authorization header must be added AFTER FormData is built, because
    // the browser sets its own Content-Type boundary.
    let token = this._accessToken;
    if (!token || Date.now() >= this._tokenExpiresAt) {
      token = await this.connect(false);
    }

    if (typeof onProgress === 'function') {
      onProgress({ loaded: 0, total: size, percent: 0 });
    }

    const res = await fetch(
      `${this.UPLOAD_ROOT}/files?uploadType=multipart&supportsAllDrives=true`,
      {
        method: 'POST',
        headers: { 'Authorization': 'Bearer ' + token },
        body: form
      }
    );

    if (!res.ok) {
      const err = await res.json().catch(() => ({}));
      throw new Error(err.error?.message || `Upload failed (HTTP ${res.status})`);
    }

    const created = await res.json();

    if (typeof onProgress === 'function') {
      onProgress({ loaded: size, total: size, percent: 100 });
    }

    App.logActivity(`Cloud backup uploaded: ${name} (${(size / 1024).toFixed(1)} KB)`, 'Cloud Backup');

    return {
      id:   created.id,
      name: created.name || name,
      size
    };
  },

  /* ========================================================================
     DOWNLOAD
     ======================================================================== */

  /**
   * Download a backup file by ID and return the parsed snapshot object.
   * Does NOT restore — the caller decides whether to apply it.
   */
  async download(fileId) {
    const res = await this._apiFetch(`/files/${encodeURIComponent(fileId)}?alt=media`);
    if (!res.ok) {
      const err = await res.json().catch(() => ({}));
      throw new Error(err.error?.message || `Download failed (HTTP ${res.status})`);
    }
    const text = await res.text();
    let parsed;
    try { parsed = JSON.parse(text); }
    catch (e) { throw new Error('The downloaded backup is not valid JSON.'); }
    if (!parsed || parsed.application !== CONFIG.APP_NAME || !parsed.data) {
      throw new Error('The downloaded file is not a valid KlazAssist backup.');
    }
    return parsed;
  },

  /* ========================================================================
     DELETE
     ======================================================================== */

  /** Permanently delete a backup file. */
  async delete(fileId) {
    const res = await this._apiFetch(`/files/${encodeURIComponent(fileId)}`, { method: 'DELETE' });
    if (!res.ok && res.status !== 204) {
      const err = await res.json().catch(() => ({}));
      throw new Error(err.error?.message || `Delete failed (HTTP ${res.status})`);
    }
    App.logActivity('Cloud backup deleted', 'Cloud Backup');
  },

  /* ========================================================================
     RESTORE
     ======================================================================== */

  /**
   * Download a cloud backup and restore it into the local database.
   * Uses the existing `DB.restoreSnapshot` atomic write path.
   *
   * @returns {number} The number of records restored.
   */
  async restore(fileId) {
    const snapshot = await this.download(fileId);
    const written = await DB.restoreSnapshot(snapshot, { replace: true, beforeReplace: () => Pages._downloadRecoveryBackup('before-cloud-restore') });
    await App.loadState();
    App.logActivity(`Cloud backup restored (${written} records)`, 'Cloud Backup');
    return written;
  },

  /* ========================================================================
     CONVENIENCE — full backup-now flow
     ======================================================================== */

  /**
   * Build a snapshot, upload it to Drive, and update the backup-hygiene
   * counters. Called from the Settings button and the dashboard reminder.
   */
  async backupNow(onProgress) {
    if (!(await this.isConfigured())) {
      throw new Error('Set a Google OAuth client ID first (Settings → Cloud Backup).');
    }

    if (typeof onProgress === 'function') {
      onProgress({ phase: 'building', percent: 0, message: 'Building snapshot…' });
    }

    const snapshot = await Pages._buildBackupSnapshot();

    if (typeof onProgress === 'function') {
      onProgress({ phase: 'uploading', percent: 10, message: 'Uploading to Google Drive…' });
    }

    const result = await this.upload(snapshot, (p) => {
      if (typeof onProgress === 'function') {
        onProgress({
          phase: 'uploading',
          percent: 10 + Math.round(p.percent * 0.9),
          message: `Uploading… ${p.percent}%`
        });
      }
    });

    // Reset the backup-hygiene counters so the reminder goes quiet.
    const nowIso = new Date().toISOString();
    try {
      await DB.setSetting('backupMeta', { lastBackupAt: nowIso, changesSinceBackup: 0 });
      await DB.setSetting('backupReminderDismissedAt', null);
      State.backupMeta = { lastBackupAt: nowIso, changesSinceBackup: 0 };
    } catch (e) { /* non-critical */ }

    if (typeof onProgress === 'function') {
      onProgress({ phase: 'done', percent: 100, message: 'Backup complete.' });
    }
    return result;
  }
};

window.CloudBackup = CloudBackup;

/* ============================================================================
   CLOUD BACKUP — Settings tab + backup list + restore confirmation
   ----------------------------------------------------------------------------
   Defined as property assignments on `Pages` at module scope, NOT as methods
   inside Pages.settings(). Pages.settings is a function body, and function
   bodies cannot contain object-literal method shorthand — the parser rejects
   `async methodName() {}` in that context.
   ============================================================================ */

Pages.renderCloudBackupSettings = async function (content) {
  const configured = await CloudBackup.isConfigured();
  const clientId   = await CloudBackup.getClientId();
  const connected  = CloudBackup.isConnected();

  let listHTML = '';
  if (configured) {
    listHTML = connected
      ? `<p class="text-sm text-muted" style="padding:16px;text-align:center;">Loading backups…</p>`
      : `<div class="cb-empty-state">
           ${icon('upload')}
           <div>Connect to Google Drive to view your backups.</div>
         </div>`;
  }

  content.innerHTML = `
    <div class="settings-section">
      <div class="settings-section-head">
        <h3>Google Drive Backup</h3>
        <p>Store JSON snapshots in a hidden folder inside your own Google Drive. Files are invisible in the Drive UI and count against your Google storage quota.</p>
      </div>

      <div class="alert alert-info mb-16">
        ${icon('info')}
        <div>
          This feature uses Google Identity Services and requires a one-time OAuth
          client ID setup. Backups are stored in the <code>appDataFolder</code> —
          a hidden, per-app folder that only KlazAssist can read. They are never
          uploaded anywhere else.
        </div>
      </div>

      <div class="form-group">
        <label for="cb-client-id">Google OAuth Client ID</label>
        <input class="form-control" id="cb-client-id"
               placeholder="1234567890-abc.apps.googleusercontent.com"
               value="${Utils.attr(clientId)}" spellcheck="false" autocomplete="off">
        <small class="text-muted">
          Get this from the Google Cloud Console → APIs &amp; Services → Credentials.
        </small>
      </div>

      <div class="flex gap-8 mb-16" style="flex-wrap:wrap;">
        <button class="btn btn-primary" id="cb-save-client">${icon('save')} Save Client ID</button>
        ${configured ? `
          <button class="btn ${connected ? 'btn-outline' : 'btn-primary'}" id="cb-connect">
            ${icon(connected ? 'xCircle' : 'check')}
            ${connected ? 'Disconnect' : 'Connect to Google Drive'}
          </button>` : ''}
      </div>
    </div>

    ${configured ? `
      <div class="settings-section">
        <div class="settings-section-head">
          <div style="display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;">
            <div>
              <h3>Backups in Drive</h3>
              <p id="cb-status">${connected ? 'Connected' : 'Not connected'}</p>
            </div>
            <div class="flex gap-8">
              <button class="btn btn-primary btn-sm" id="cb-backup-now" ${connected ? '' : 'disabled'}>
                ${icon('upload')} Backup Now
              </button>
              <button class="btn btn-outline btn-sm" id="cb-refresh" ${connected ? '' : 'disabled'}>
                ${icon('history')} Refresh
              </button>
            </div>
          </div>
        </div>
        <div id="cb-list">${listHTML}</div>
      </div>` : ''}
  `;

  /* ---------- Bindings ---------- */

  content.querySelector('#cb-save-client').onclick = async () => {
    const id = content.querySelector('#cb-client-id').value.trim();
    try {
      await CloudBackup.setClientId(id);
      UI.toast(id ? 'Client ID saved.' : 'Client ID cleared.', 'success');
      Pages.settings(document.getElementById('content').firstElementChild);
    } catch (e) {
      UI.toast(e.message, 'warning', 5000);
    }
  };

  const connectBtn = content.querySelector('#cb-connect');
  if (connectBtn) {
    connectBtn.onclick = async () => {
      if (CloudBackup.isConnected()) {
        await CloudBackup.disconnect();
        UI.toast('Disconnected from Google Drive.', 'info');
      } else {
        try {
          await CloudBackup.connect(true);
          UI.toast('Connected to Google Drive.', 'success');
        } catch (e) {
          UI.toast('Could not connect: ' + e.message, 'error', 5000);
          return;
        }
      }
      Pages.settings(document.getElementById('content').firstElementChild);
    };
  }

  const backupNowBtn = content.querySelector('#cb-backup-now');
  if (backupNowBtn) {
    backupNowBtn.onclick = async () => {
      backupNowBtn.disabled = true;
      const status = content.querySelector('#cb-status');
      try {
        if (status) status.textContent = 'Building snapshot…';
        await CloudBackup.backupNow((p) => {
          if (status) status.textContent = p.message || 'Working…';
        });
        UI.toast('Backup uploaded to Google Drive.', 'success');
        Pages.settings(document.getElementById('content').firstElementChild);
      } catch (e) {
        console.error('Cloud backup failed:', e);
        UI.toast('Backup failed: ' + e.message, 'error', 6000);
        if (status) status.textContent = 'Not connected';
        backupNowBtn.disabled = false;
      }
    };
  }

  const refreshBtn = content.querySelector('#cb-refresh');
  if (refreshBtn) {
    refreshBtn.onclick = () => Pages._renderCloudBackupList(content);
  }

  if (configured && connected) {
    setTimeout(() => Pages._renderCloudBackupList(content), 50);
  }
};

Pages._renderCloudBackupList = async function (content) {
  const listEl = content.querySelector('#cb-list');
  if (!listEl) return;

  listEl.innerHTML = `<p class="text-sm text-muted" style="padding:16px;text-align:center;">Loading…</p>`;

  try {
    const files = await CloudBackup.listBackups();

    if (!files.length) {
      listEl.innerHTML = `
        <div class="cb-empty-state">
          ${icon('folder')}
          <div>No backups yet. Click <strong>Backup Now</strong> to create one.</div>
        </div>`;
      return;
    }

    listEl.innerHTML = `
      <div class="table-wrap">
        <table class="data-table" style="font-size:12.5px;">
          <thead>
            <tr>
              <th>Backup</th>
              <th style="width:100px;">Size</th>
              <th style="width:170px;">Created</th>
              <th style="width:180px;text-align:right;">Actions</th>
            </tr>
          </thead>
          <tbody>
            ${files.map(f => `
              <tr data-cb-file="${Utils.attr(f.id)}">
                <td><strong>${Utils.esc(f.name || 'Untitled')}</strong></td>
                <td>${f.size ? (Number(f.size) / 1024).toFixed(1) + ' KB' : '—'}</td>
                <td class="text-xs text-muted">${Utils.formatDateTime(f.createdTime)}</td>
                <td class="table-actions" style="justify-content:flex-end;">
                  <button class="btn btn-sm btn-primary" data-cb-restore="${Utils.attr(f.id)}" title="Restore this backup">
                    ${icon('download')} Restore
                  </button>
                  <button class="icon-btn" data-cb-delete="${Utils.attr(f.id)}" title="Delete">
                    ${icon('trash')}
                  </button>
                </td>
              </tr>`).join('')}
          </tbody>
        </table>
      </div>`;

    listEl.querySelectorAll('[data-cb-restore]').forEach(btn => {
      btn.onclick = () => Pages._confirmCloudRestore(btn.dataset.cbRestore);
    });
    listEl.querySelectorAll('[data-cb-delete]').forEach(btn => {
      btn.onclick = async () => {
        UI.confirm({
          title: 'Delete cloud backup?',
          message: 'This permanently deletes the backup from your Google Drive. It cannot be recovered.',
          confirmText: 'Delete',
          confirmClass: 'btn-danger',
          onConfirm: async () => {
            try {
              await CloudBackup.delete(btn.dataset.cbDelete);
              UI.toast('Backup deleted.', 'success');
              Pages._renderCloudBackupList(content);
            } catch (e) {
              UI.toast('Delete failed: ' + e.message, 'error', 5000);
            }
          }
        });
      };
    });
  } catch (e) {
    console.error('List backups failed:', e);
    listEl.innerHTML = `
      <div class="alert alert-danger" style="margin:16px;">
        ${icon('alert')}
        <div>${Utils.esc(e.message)}</div>
      </div>`;
  }
};

Pages._confirmCloudRestore = function (fileId) {
  UI.confirm({
    title: 'Restore from Google Drive?',
    message: `
      This will <strong>replace</strong> every record on this device with the
      selected backup. Anything not in the backup will be deleted.
      <br><br>
      Your current data will be overwritten. Consider exporting a local backup first.
    `,
    confirmText: 'Restore',
    confirmClass: 'btn-danger',
    onConfirm: async () => {
      UI.toast('Downloading and restoring…', 'info', 3000);
      try {
        const written = await CloudBackup.restore(fileId);
        UI.toast(`Restored ${written.toLocaleString()} records.`, 'success', 5000);
        App.navigate('dashboard');
      } catch (e) {
        console.error('Cloud restore failed:', e);
        UI.toast('Restore failed: ' + e.message, 'error', 7000);
      }
    }
  });
};

window.Pages = Pages;
window.App = App;
window.DB = DB;
window.State = State;
window.Utils = Utils;
window.UI = UI;
window.CONFIG = CONFIG;
window.GRADING_POLICIES = GRADING_POLICIES;
window.GradingEngine = GradingEngine;
window.TransmutationEngine = TransmutationEngine;
window.AttendancePolicy = AttendancePolicy;
window.ValidationEngine = ValidationEngine;
window.SampleData = SampleData;
window.Auth = Auth;
window.Session = Session;
window.Security = Security;
window.AuthUI = AuthUI;
window.SetupWizard = SetupWizard;
window.PhilIriPdfImporter = PhilIriPdfImporter;

document.addEventListener('DOMContentLoaded', () => {
  window.addEventListener('error', (e) => { console.error('Uncaught error:', e.error || e.message); });
  window.addEventListener('unhandledrejection', (e) => { console.error('Unhandled promise rejection:', e.reason); });

/* ============================================================================
   DRAFT RESTORERS
   ----------------------------------------------------------------------------
   Each entry teaches `Unsaved` how to rehydrate a saved draft back into its
   source form. Without a restorer, `Unsaved._restore` falls back to
   downloading the raw payload as JSON.

   Placement note: these calls reference `Unsaved` (declared above with
   `const`) and `Pages` (declared much earlier). Both must exist by the
   time this module-scope code runs, which is why it sits at the very
   bottom of `main.ts`.
   ============================================================================ */

  /* ============================================================================
     VERSION LABEL SYNC
     ============================================================================ */
  (function syncAppVersion() {
    function apply() {
      try {
        const raw = (typeof CONFIG !== 'undefined' && CONFIG && CONFIG.VERSION)
          ? String(CONFIG.VERSION).trim()
          : '2.0.0';
        const label = raw.charAt(0).toLowerCase() === 'v' ? raw : ('v' + raw);
        const nodes = document.querySelectorAll('[data-app-version]');
        nodes.forEach(el => { el.textContent = label; });
        return nodes.length;
      } catch (e) {
        console.warn('[KlazAssist] Version sync failed:', e);
        return -1;
      }
    }

    function boot() {
      apply();
      if (typeof MutationObserver === 'function') {
        const obs = new MutationObserver(() => apply());
        ['app', 'login-screen', 'setup-screen'].forEach(id => {
          const el = document.getElementById(id);
          if (el) obs.observe(el, { attributes: true, attributeFilter: ['class'] });
        });
      }
      setTimeout(apply, 500);
      setTimeout(apply, 2000);
    }

    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', boot);
    } else {
      boot();
    }
  })();

  /* ---------------------------------------------------------------------------
     PWA — React to service-worker updates and expose an install trigger.
     --------------------------------------------------------------------------- */
  window.addEventListener('klaz:update-ready', () => {
    UI.toast('A new version of KlazAssist is ready — reloading…', 'info', 3500);
    setTimeout(async () => {
      try {
        const reg = await navigator.serviceWorker.getRegistration();
        if (reg && reg.waiting) reg.waiting.postMessage('SKIP_WAITING');
      } catch (e) { /* ignore */ }
    }, 1200);
  });

(window as any).installKlazAssist = async function () {
  // ---- Environment detection ----
  const ua = navigator.userAgent || '';
  const isIOS     = /iPhone|iPad|iPod/.test(ua)
                 || (/Macintosh/.test(ua) && navigator.maxTouchPoints > 1);
  const isSafari  = /Safari/.test(ua)
                 && !/Chrome|Chromium|Edg|OPR|CriOS|FxiOS|Brave/.test(ua);
  const standalone = (window.matchMedia && window.matchMedia('(display-mode: standalone)').matches)
                 || (typeof (navigator as any).standalone === 'boolean' && (navigator as any).standalone === true);

  // ---- Already installed? ----
  if (standalone) {
    UI.toast('KlazAssist is already installed on this device.', 'info', 4000);
    return;
  }

  // ---- iOS Safari: no beforeinstallprompt — show manual steps ----
  if (isIOS) {
    UI.modal({
      title: 'Install KlazAssist',
      body: `
        <p style="font-size:13px;line-height:1.6;margin-bottom:14px;">
          iOS Safari doesn't support one-click install. Add KlazAssist to your
          Home Screen manually — it takes about 10 seconds.
        </p>
        <ol style="font-size:13.5px;line-height:1.9;padding-left:22px;color:var(--text);">
          <li>Tap the <strong>Share</strong> button
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"
                   style="width:14px;height:14px;display:inline-block;vertical-align:-2px;margin:0 2px;">
                <path d="M4 12v8a2 2 0 002 2h12a2 2 0 002-2v-8"/>
                <polyline points="16 6 12 2 8 6"/><line x1="12" y1="2" x2="12" y2="15"/>
              </svg>
              at the bottom of Safari.</li>
          <li>Scroll down and tap <strong>Add to Home Screen</strong>.</li>
          <li>Tap <strong>Add</strong> in the top-right corner.</li>
        </ol>
        <div class="alert alert-info" style="font-size:12px;margin-top:16px;">
          ${icon('info')}
          <div>
            Once installed, Safari upgrades KlazAssist's storage to
            <strong>persistent</strong> — the browser will no longer be allowed to
            silently delete your data after 7 days of inactivity.
          </div>
        </div>`,
      footer: `<button class="btn btn-primary" data-close>Got it</button>`
    });
    return;
  }

  // ---- Desktop Safari: File → Add to Dock ----
  if (isSafari && !isIOS) {
    UI.modal({
      title: 'Install KlazAssist',
      body: `
        <p style="font-size:13px;line-height:1.6;margin-bottom:14px;">
          Safari on macOS installs PWAs to the Dock rather than the Home Screen.
        </p>
        <ol style="font-size:13.5px;line-height:1.9;padding-left:22px;color:var(--text);">
          <li>Open the <strong>File</strong> menu in the menu bar.</li>
          <li>Choose <strong>Add to Dock…</strong>.</li>
          <li>Confirm the name and click <strong>Add</strong>.</li>
        </ol>`,
      footer: `<button class="btn btn-primary" data-close>Got it</button>`
    });
    return;
  }

  // ---- Chromium / Android: use the deferred prompt ----
  const prompt = (window as any).__klazInstallPrompt;
  if (!prompt) {
    UI.toast(
      'Install isn\'t available right now. Your browser may not support PWA installation, ' +
      'or the app has already been installed. Try opening the browser menu and looking for ' +
      '“Install App” or “Add to Home Screen”.',
      'info', 8000
    );
    return;
  }

  try {
    prompt.prompt();
    const choice = await prompt.userChoice;
    // Clear the deferred prompt immediately — it can only be used once.
    (window as any).__klazInstallPrompt = null;

    if (choice && choice.outcome === 'accepted') {
      UI.toast('KlazAssist installed — open it from your home screen or dock.', 'success', 5000);
      try { App.logActivity('PWA installed', 'System'); } catch (_) {}
    } else {
      UI.toast('Installation cancelled.', 'info', 3000);
    }
  } catch (e) {
    // Some browsers throw if the prompt is stale. Clear it and tell the user.
    console.warn('[KlazAssist] Install prompt failed:', e);
    (window as any).__klazInstallPrompt = null;
    UI.toast(
      'Installation failed. Try reloading the page, then use your browser\'s ' +
      '“Install App” option from the menu.',
      'warning', 7000
    );
  }
};

  // If this window was opened as a learner/presenter view, take over the
  // entire page. Do NOT run the normal app bootstrap.
  if (Presenter.isLearnerWindow()) {
    Presenter.initLearnerWindow();
    return;
  }


  // Capture the browser's install prompt so we can offer our own button.
  let _deferredInstallPrompt = null;

  window.addEventListener('beforeinstallprompt', (e) => {
    e.preventDefault();
    _deferredInstallPrompt = e;
    const btn = document.getElementById('install-btn');
    if (btn) btn.classList.remove('hidden');
  });

  window.addEventListener('appinstalled', () => {
    _deferredInstallPrompt = null;
    const btn = document.getElementById('install-btn');
    if (btn) btn.classList.add('hidden');
    if (window.App && App.logActivity) App.logActivity('App installed to home screen', 'System');
    if (window.UI && UI.toast) UI.toast('KlazAssist installed. It will now work offline.', 'success', 5000);
  });

  App.promptInstall = async function () {
    if (!_deferredInstallPrompt) {
      UI.toast('Install prompt not available. Use your browser menu → Install app.', 'info', 5000);
      return;
    }
    _deferredInstallPrompt.prompt();
    try {
      const choice = await _deferredInstallPrompt.userChoice;
      if (choice && choice.outcome === 'accepted') {
        UI.toast('Installing…', 'info', 2000);
      }
    } catch (e) { /* user dismissed */ }
    _deferredInstallPrompt = null;
    const btn = document.getElementById('install-btn');
    if (btn) btn.classList.add('hidden');
  };
  /* ============================================================================
     Restore handler for saved Lesson Plan drafts
     ----------------------------------------------------------------------------
     Registered inside DOMContentLoaded so both `Unsaved` and `Pages` are fully
     initialized. At module scope, `Unsaved` is declared later in the file than
     `Pages`, so referencing it there would throw a temporal-dead-zone error.
     ============================================================================ */
  Unsaved.registerRestorer('lesson-planner', async (payload) => {
    document.querySelectorAll('.modal-overlay').forEach(x => x.remove());
    await Pages.openLessonModal(payload.existingId);
    await new Promise(r => setTimeout(r, 150));

    const root = document.querySelector('.modal-overlay');
    if (!root) throw new Error('Lesson Plan modal did not open.');

    const set = (id, v) => {
      const el = root.querySelector('#' + id);
      if (el) el.value = v || '';
    };
    set('lp-date',       payload.fields.date);
    const savedTerm = String(payload.fields.term || payload.fields.quarter || '').trim();
    const savedTermMatch = savedTerm.match(/(?:term|quarter)\s*([1-3])/i);
    set('lp-quarter', savedTermMatch ? 'Term ' + savedTermMatch[1] : '');
    set('lp-area',       payload.fields.learningArea);
    set('lp-topic',      payload.fields.topic);
    set('lp-comp',       payload.fields.competency);
    set('lp-objectives', payload.fields.objectives);
    set('lp-content',    payload.fields.content);
    set('lp-resources',  payload.fields.resources);
    set('lp-assessment', payload.fields.assessment);
    set('lp-assignment', payload.fields.assignment);
    set('lp-remarks',    payload.fields.remarks);

    const gradeSel = root.querySelector('#lp-grade');
    if (gradeSel && payload.fields.gradeLevel) {
      const known = Array.from(gradeSel.options).some(o => o.value === payload.fields.gradeLevel);
      if (known) gradeSel.value = payload.fields.gradeLevel;
    }

    root.querySelectorAll('textarea[data-proc]').forEach(t => {
      if (payload.procedures && t.dataset.proc in payload.procedures) {
        t.value = payload.procedures[t.dataset.proc];
      }
    });

    Unsaved.mark('lesson-planner');
  });

  App.bootstrap();
});